INSERT INTO `real_estate_faqs` (`id`, `category`, `intent_name`, `user_question`, `question_variations`, `answer`, `required_information`, `agent_handoff`, `keywords`, `language`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Buying', 'home_buying_start', 'How do I start the process of buying a home?', NULL, 'The first step is understanding your budget, checking your financing options, and getting pre-approved for a mortgage if needed. After that, you can begin searching for properties that match your needs and budget.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(2, 'Buying', 'buying_process_steps', 'What are the steps to buy a house?', NULL, 'The typical home-buying process includes determining your budget, mortgage pre-approval, finding a property, viewing homes, making an offer, negotiating terms, completing inspections, finalizing financing, and closing the purchase.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(3, 'Buying', 'first_time_buyer', 'I am a first-time home buyer. Where should I begin?', NULL, 'Start by reviewing your finances, understanding your monthly budget, checking your credit score, exploring mortgage options, and speaking with a real estate professional who can guide you through the process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(4, 'Buying', 'buyer_agent_help', 'Do I need a real estate agent to buy a home?', NULL, 'While it is possible to buy without an agent, a real estate agent can help you find suitable properties, understand market values, negotiate offers, handle paperwork, and guide you through closing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(5, 'Buying', 'home_search_help', 'Can you help me find a home?', NULL, 'Yes, I can help you search for properties based on your preferred location, budget, property type, size, and other requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(6, 'Buying', 'buying_timeline', 'How long does it take to buy a house?', NULL, 'The timeline varies depending on financing, market conditions, negotiations, inspections, and closing requirements. Many purchases take several weeks to a few months from search to closing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(7, 'Buying', 'house_budget', 'How much house can I afford?', NULL, 'Your home budget depends on your income, existing debts, credit score, down payment, interest rates, and monthly expenses. A mortgage professional can provide a more accurate affordability estimate.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(8, 'Buying', 'down_payment', 'How much down payment do I need to buy a home?', NULL, 'The required down payment depends on the loan program, location, property type, and your financial situation. Some buyers qualify for lower down payment options.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(9, 'Buying', 'mortgage_preapproval', 'Should I get pre-approved before looking for a home?', NULL, 'Yes, getting pre-approved helps you understand your budget, shows sellers you are a serious buyer, and can make your offer stronger.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(10, 'Buying', 'credit_score', 'What credit score do I need to buy a house?', NULL, 'Credit requirements vary depending on the lender and loan program. A stronger credit score may help you qualify for better interest rates and loan terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(11, 'Buying', 'home_viewing', 'How many homes should I see before buying?', NULL, 'There is no set number. Some buyers find the right home quickly, while others view many properties before making a decision.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(12, 'Buying', 'property_requirements', 'What information should I provide when looking for a home?', NULL, 'Helpful information includes your preferred location, budget, property type, number of bedrooms, desired features, timeline, and financing status.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(13, 'Buying', 'online_home_search', 'Can I search for homes online?', NULL, 'Yes, online listings are a useful starting point. A real estate professional can provide additional market information, arrange viewings, and help evaluate properties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(14, 'Buying', 'home_location', 'How do I choose the right neighborhood?', NULL, 'Consider commute times, schools, amenities, safety, future development, property values, and your lifestyle preferences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(15, 'Buying', 'new_vs_existing_home', 'Should I buy a new home or an older home?', NULL, 'New homes may offer modern features and fewer immediate repairs, while older homes may have established neighborhoods and unique characteristics.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(16, 'Buying', 'condo_vs_house', 'Should I buy a condo or a house?', NULL, 'Condos may offer lower maintenance and shared amenities, while houses usually provide more privacy and space. The best choice depends on your lifestyle and budget.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(17, 'Buying', 'investment_or_primary', 'Should I buy a home to live in or as an investment?', NULL, 'This depends on your financial goals, lifestyle, and long-term plans. Primary residences and investment properties have different considerations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(18, 'Buying', 'offer_process', 'How do I make an offer on a house?', NULL, 'Your agent can help prepare an offer based on market conditions, property value, comparable sales, and your budget.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(19, 'Buying', 'offer_acceptance', 'What happens after my offer is accepted?', NULL, 'After acceptance, you typically complete inspections, finalize financing, review documents, and prepare for closing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(20, 'Buying', 'home_inspection', 'Do I need a home inspection?', NULL, 'A home inspection can help identify potential issues with the property before completing the purchase and help you make informed decisions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(21, 'Buying', 'appraisal', 'What is a home appraisal?', NULL, 'An appraisal is an evaluation of a property’s market value, usually completed by a qualified professional and often required by lenders.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(22, 'Buying', 'closing_process', 'What happens at closing?', NULL, 'Closing is the final step where documents are signed, funds are transferred, ownership is officially transferred, and you receive the keys.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(23, 'Buying', 'closing_costs', 'What are closing costs?', NULL, 'Closing costs are expenses associated with completing a real estate transaction, including possible lender fees, legal fees, taxes, insurance, and other charges.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(24, 'Buying', 'buying_mistakes', 'What mistakes should first-time buyers avoid?', NULL, 'Common mistakes include not checking affordability, skipping inspections, making emotional decisions, and not understanding all purchase costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(25, 'Buying', 'real_estate_consultation', 'Can a real estate agent help me understand the buying process?', NULL, 'Yes, a real estate agent can explain the process, answer questions, help find properties, negotiate offers, and guide you through the transaction.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:18', '2026-08-03 07:34:18'),
(26, 'Mortgage', 'what_is_mortgage', 'What is a mortgage?', NULL, 'A mortgage is a loan used to purchase a property. The borrower repays the loan over an agreed period with interest according to the lender terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(27, 'Mortgage', 'how_much_can_borrow', 'How much money can I borrow for a home?', NULL, 'The amount you can borrow depends on your income, debts, credit score, down payment, interest rates, and lender requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(28, 'Mortgage', 'monthly_payment', 'How much will my monthly mortgage payment be?', NULL, 'Your monthly payment depends on the loan amount, interest rate, loan term, property taxes, insurance, and other costs associated with the property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(29, 'Mortgage', 'mortgage_calculator', 'Can you calculate my mortgage payment?', NULL, 'Yes, I can help estimate your mortgage payment. I will need information such as purchase price, down payment, interest rate, and loan term.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(30, 'Mortgage', 'mortgage_preapproval_process', 'How do I get mortgage pre-approval?', NULL, 'To get pre-approved, you typically provide income information, employment details, credit information, debts, and financial documents to a lender.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(31, 'Mortgage', 'preapproval_time', 'How long does mortgage pre-approval take?', NULL, 'Mortgage pre-approval timelines vary by lender, but many applications can be reviewed within a few days if all required documents are provided.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(32, 'Mortgage', 'preapproval_expire', 'How long is a mortgage pre-approval valid?', NULL, 'Mortgage pre-approval validity depends on the lender. Many approvals remain valid for a limited period and may need to be updated if your situation changes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(33, 'Mortgage', 'interest_rate', 'What affects mortgage interest rates?', NULL, 'Mortgage rates are affected by market conditions, inflation, economic factors, loan type, credit score, down payment, and lender policies.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(34, 'Mortgage', 'fixed_vs_variable', 'Should I choose a fixed or variable mortgage rate?', NULL, 'A fixed-rate mortgage keeps your interest rate the same during the agreed term, while a variable-rate mortgage can change based on market conditions. The right choice depends on your financial goals and risk tolerance.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(35, 'Mortgage', 'good_credit_score', 'How can I improve my credit score before buying?', NULL, 'You can improve your credit score by paying bills on time, reducing debt, avoiding unnecessary credit applications, and reviewing your credit report for errors.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(36, 'Mortgage', 'bad_credit_home_purchase', 'Can I buy a house with bad credit?', NULL, 'It may be possible to buy with a lower credit score, but loan options, interest rates, and requirements may vary. Speaking with a mortgage professional can help identify available options.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(37, 'Mortgage', 'self_employed_mortgage', 'Can self-employed people get a mortgage?', NULL, 'Yes, self-employed buyers can apply for mortgages. Lenders may require additional documentation such as tax returns, business records, and proof of income.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(38, 'Mortgage', 'income_needed', 'How much income do I need to buy a house?', NULL, 'The required income depends on the home price, loan amount, interest rate, monthly debts, and lender guidelines.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(39, 'Mortgage', 'debt_affects_mortgage', 'Do my debts affect my mortgage approval?', NULL, 'Yes, existing debts can affect how much you qualify to borrow because lenders consider your debt-to-income ratio.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(40, 'Mortgage', 'down_payment_source', 'Can my down payment come from a gift?', NULL, 'Some loan programs allow gifted funds for a down payment. Requirements vary depending on the lender and loan type.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(41, 'Mortgage', 'closing_cost_financing', 'Can closing costs be included in my mortgage?', NULL, 'In some situations, closing costs may be covered through specific loan programs, lender credits, or negotiated terms. Your lender can explain available options.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(42, 'Mortgage', 'loan_term', 'What mortgage term should I choose?', NULL, 'Common mortgage terms vary by location and lender. A shorter term may reduce total interest costs, while a longer term may provide lower monthly payments.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(43, 'Mortgage', 'refinance', 'What does refinancing a mortgage mean?', NULL, 'Refinancing means replacing your existing mortgage with a new loan, often to change the interest rate, payment amount, loan term, or access equity.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(44, 'Mortgage', 'when_refinance', 'When should I refinance my mortgage?', NULL, 'Refinancing may make sense when interest rates improve, your financial situation changes, or you want to adjust your mortgage terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(45, 'Mortgage', 'home_equity', 'What is home equity?', NULL, 'Home equity is the difference between your property value and the amount you still owe on your mortgage.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(46, 'Mortgage', 'use_home_equity', 'Can I use my home equity?', NULL, 'Depending on your financial situation and local regulations, you may be able to access home equity through refinancing or other lending options.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(47, 'Mortgage', 'mortgage_insurance', 'What is mortgage insurance?', NULL, 'Mortgage insurance protects lenders against certain risks and may be required depending on the loan type, down payment amount, and regulations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(48, 'Mortgage', 'loan_denied', 'What should I do if my mortgage application is denied?', NULL, 'If your mortgage is denied, review the reason with your lender, improve financial factors if needed, and explore alternative financing options.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(49, 'Mortgage', 'mortgage_documents', 'What documents are needed for a mortgage application?', NULL, 'Common documents include proof of income, employment information, bank statements, identification, tax documents, and details about existing debts.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(50, 'Mortgage', 'cash_buyer_vs_mortgage', 'Is it better to buy with cash or get a mortgage?', NULL, 'Buying with cash may simplify the transaction and avoid interest costs, while using a mortgage may allow you to preserve cash for other investments or expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:34:57', '2026-08-03 07:34:57'),
(51, 'Selling', 'how_to_sell_home', 'How do I sell my house?', NULL, 'The home selling process usually includes preparing your property, determining the right price, marketing the listing, reviewing offers, negotiating terms, completing inspections, and closing the sale.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(52, 'Selling', 'home_value_estimate', 'How much is my house worth?', NULL, 'Your home value depends on factors such as location, property size, condition, recent comparable sales, market conditions, and buyer demand.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(53, 'Selling', 'property_valuation', 'Can you provide a home valuation?', NULL, 'Yes, a real estate professional can help estimate your property value using market data, comparable properties, and current market conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(54, 'Selling', 'best_time_to_sell', 'When is the best time to sell my home?', NULL, 'The best time to sell depends on your personal situation, local market conditions, buyer demand, interest rates, and economic factors.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(55, 'Selling', 'prepare_home_for_sale', 'How should I prepare my home before selling?', NULL, 'Preparing your home may include cleaning, decluttering, making necessary repairs, improving curb appeal, and staging the property to attract buyers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(56, 'Selling', 'repairs_before_selling', 'What repairs should I make before selling my house?', NULL, 'Focus on repairs that improve buyer confidence and property value, such as fixing major issues, updating worn areas, improving appearance, and addressing safety concerns.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(57, 'Selling', 'home_staging', 'Is home staging worth it?', NULL, 'Home staging can help buyers visualize the property, improve presentation, and potentially increase buyer interest. The impact depends on the market and property type.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(58, 'Selling', 'listing_price', 'How do I decide the listing price for my home?', NULL, 'The listing price should be based on comparable sales, current market conditions, property features, location, and your selling goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(59, 'Selling', 'overpricing_home', 'What happens if I price my home too high?', NULL, 'Overpricing can reduce buyer interest, increase time on the market, and may require future price reductions. Proper pricing helps attract qualified buyers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(60, 'Selling', 'underpricing_home', 'Should I price my home lower to get more offers?', NULL, 'A strategic price may attract more buyers and create competition, but pricing decisions should consider market conditions and your selling objectives.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(61, 'Selling', 'real_estate_commission', 'How much commission do real estate agents charge?', NULL, 'Real estate commissions vary depending on location, services provided, market conditions, and the agreement between the seller and the agent.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(62, 'Selling', 'seller_closing_costs', 'What costs do sellers pay when selling a home?', NULL, 'Seller costs may include agent fees, closing expenses, taxes, legal fees, repairs, moving costs, and other transaction-related expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(63, 'Selling', 'selling_timeline', 'How long does it take to sell a house?', NULL, 'The selling timeline depends on market conditions, pricing strategy, property condition, buyer demand, negotiations, inspections, and closing requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(64, 'Selling', 'marketing_home', 'How will my home be marketed?', NULL, 'Marketing may include online listings, professional photos, virtual tours, social media promotion, open houses, buyer networks, and targeted advertising.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(65, 'Selling', 'professional_photos', 'Are professional photos important when selling?', NULL, 'Yes, high-quality photos can improve online presentation, attract more buyers, and help create a strong first impression.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(66, 'Selling', 'open_house', 'Should I have an open house?', NULL, 'An open house can increase exposure and allow buyers to view the property. Its effectiveness depends on your market and property type.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(67, 'Selling', 'reviewing_offers', 'How do I choose the best offer?', NULL, 'The best offer is not always the highest price. Consider financing strength, conditions, closing timeline, buyer qualifications, and overall terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(68, 'Selling', 'multiple_offers', 'What happens if I receive multiple offers?', NULL, 'When multiple offers are received, you can compare terms and negotiate with buyers to select the offer that best matches your goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(69, 'Selling', 'accept_offer', 'Can I reject an offer on my house?', NULL, 'Yes, sellers generally have the option to accept, reject, or negotiate offers based on the terms and applicable agreements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(70, 'Selling', 'home_inspection_seller', 'What happens during a buyer inspection?', NULL, 'A buyer inspection allows the buyer to evaluate the property condition. The results may influence negotiations depending on the purchase agreement.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(71, 'Selling', 'seller_negotiation', 'Can I negotiate after receiving an offer?', NULL, 'Yes, sellers can negotiate price, conditions, closing dates, repairs, and other terms before accepting an offer.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(72, 'Selling', 'selling_before_buying', 'Should I sell my current home before buying another one?', NULL, 'This depends on your financial situation, market conditions, timing needs, and ability to manage two properties or temporary housing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(73, 'Selling', 'selling_with_mortgage', 'Can I sell my home if I still have a mortgage?', NULL, 'Yes, many homeowners sell while having an active mortgage. The remaining mortgage balance is typically paid from the sale proceeds at closing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(74, 'Selling', 'capital_gains_home_sale', 'Will I pay taxes when selling my home?', NULL, 'Tax rules vary depending on location, ownership period, property use, and personal circumstances. A tax professional can provide guidance for your situation.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(75, 'Selling', 'seller_agent_choice', 'How do I choose the right real estate agent to sell my home?', NULL, 'Look for an agent with local market knowledge, strong communication skills, marketing experience, negotiation ability, and a proven track record.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:29', '2026-08-03 07:35:29'),
(76, 'Renting', 'how_to_rent_property', 'How do I rent a property?', NULL, 'The rental process usually includes finding a suitable property, submitting an application, providing required documents, completing approval, signing a lease agreement, and moving in.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(77, 'Renting', 'find_rental_home', 'Can you help me find a rental property?', NULL, 'Yes, I can help you search for rental properties based on your preferred location, budget, property type, size, and move-in date.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(78, 'Renting', 'rental_application', 'How do I apply for a rental property?', NULL, 'To apply for a rental, you typically complete an application form and provide identification, income verification, employment details, and rental history.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(79, 'Renting', 'rental_requirements', 'What do I need to rent a home?', NULL, 'Common rental requirements include proof of income, identification, credit history, rental references, and sometimes a security deposit.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(80, 'Renting', 'credit_score_renting', 'What credit score do I need to rent a property?', NULL, 'Credit score requirements vary by landlord and location. A stronger credit history may improve your chances of approval and favorable rental terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(81, 'Renting', 'security_deposit', 'What is a security deposit?', NULL, 'A security deposit is money paid by a tenant to protect the landlord against unpaid rent or property damage. Rules regarding deposits vary by location.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(82, 'Renting', 'rent_price', 'How much rent can I afford?', NULL, 'A common guideline is to keep rent within a reasonable percentage of your monthly income while considering other expenses, debts, and financial goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(83, 'Renting', 'rental_price_calculation', 'How is rental price determined?', NULL, 'Rental prices are influenced by location, property size, condition, amenities, market demand, comparable rentals, and local economic conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(84, 'Renting', 'lease_agreement', 'What is a lease agreement?', NULL, 'A lease agreement is a legal contract between a landlord and tenant that outlines rental terms, responsibilities, payment details, and conditions of occupancy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(85, 'Renting', 'lease_length', 'How long are rental agreements usually?', NULL, 'Lease terms vary depending on the property and landlord. Common agreements may include short-term or longer-term rental periods.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(86, 'Renting', 'breaking_lease', 'Can I break my lease early?', NULL, 'Breaking a lease depends on the agreement terms, local laws, and circumstances. Review your lease and discuss options with your landlord or property manager.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(87, 'Renting', 'tenant_screening', 'How are rental applications approved?', NULL, 'Landlords typically review income, employment, credit history, rental history, references, and other application details before approval.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(88, 'Renting', 'rental_viewing', 'Can I schedule a rental property viewing?', NULL, 'Yes, you can schedule a viewing to inspect the property, ask questions, and determine if it meets your needs before applying.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(89, 'Renting', 'rent_negotiation', 'Can I negotiate the rent price?', NULL, 'In some situations, rent may be negotiable depending on market conditions, property availability, lease terms, and landlord preferences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(90, 'Renting', 'pets_in_rental', 'Can I have pets in a rental property?', NULL, 'Pet policies vary by property and landlord. Some rentals allow pets with additional conditions, fees, or restrictions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(91, 'Renting', 'rental_utilities', 'Who pays utilities in a rental property?', NULL, 'Utility responsibilities depend on the lease agreement. Some properties include certain utilities while others require tenants to pay separately.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(92, 'Renting', 'rental_inspection', 'Can a landlord inspect my rental property?', NULL, 'Landlords may have inspection rights depending on the lease agreement and local regulations. Proper notice is usually required.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(93, 'Renting', 'moving_into_rental', 'What should I do before moving into a rental?', NULL, 'Before moving in, review your lease, complete a property inspection, document existing conditions, arrange utilities, and confirm move-in details.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(94, 'Renting', 'move_out_process', 'What is the process for moving out of a rental?', NULL, 'Moving out usually involves providing notice, completing required cleaning or repairs, returning keys, and completing a final inspection.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(95, 'Renting', 'getting_security_deposit_back', 'How do I get my security deposit back?', NULL, 'To improve your chances of receiving your deposit back, follow lease requirements, pay outstanding balances, clean the property, and document its condition.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(96, 'Renting', 'rental_property_management', 'What does a property manager do?', NULL, 'A property manager handles rental operations such as tenant communication, maintenance coordination, rent collection, inspections, and administrative tasks.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(97, 'Renting', 'landlord_responsibilities', 'What are a landlord responsibilities?', NULL, 'Landlord responsibilities typically include maintaining the property, handling required repairs, following rental laws, and respecting tenant rights.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(98, 'Renting', 'tenant_responsibilities', 'What are tenant responsibilities?', NULL, 'Tenant responsibilities usually include paying rent on time, maintaining the property, following lease rules, and reporting issues promptly.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(99, 'Renting', 'rent_vs_buy', 'Should I rent or buy a home?', NULL, 'The best choice depends on your finances, lifestyle, future plans, market conditions, and how long you plan to stay in the area.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(100, 'Renting', 'rental_market', 'How do I know if rental prices are fair?', NULL, 'Rental prices can be compared by reviewing similar properties in the same area, considering features, condition, location, and current market demand.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:35:52', '2026-08-03 07:35:52'),
(101, 'Investment', 'is_real_estate_good_investment', 'Is real estate a good investment?', NULL, 'Real estate can be a long-term investment opportunity through rental income, property appreciation, and equity growth. However, returns depend on location, market conditions, financing, and property management.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(102, 'Investment', 'how_start_investing', 'How do I start investing in real estate?', NULL, 'Start by defining your investment goals, understanding your budget, researching markets, evaluating properties, reviewing financing options, and creating a strategy that fits your goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(103, 'Investment', 'rental_property_investment', 'Should I buy a rental property?', NULL, 'A rental property may provide income and long-term appreciation, but investors should consider purchase costs, maintenance, vacancies, financing, taxes, and property management responsibilities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(104, 'Investment', 'real_estate_roi', 'How do I calculate real estate ROI?', NULL, 'Real estate ROI is calculated by comparing your investment costs with the income or profit generated from the property. Factors may include rental income, expenses, appreciation, and financing costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(105, 'Investment', 'cash_flow', 'What is cash flow in real estate?', NULL, 'Cash flow is the amount of money remaining after rental income is collected and expenses such as mortgage payments, taxes, insurance, maintenance, and management costs are paid.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(106, 'Investment', 'positive_cash_flow', 'What is a positive cash flow property?', NULL, 'A positive cash flow property generates more income than its operating expenses and financing costs, creating monthly profit for the owner.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(107, 'Investment', 'negative_cash_flow', 'What is negative cash flow in real estate?', NULL, 'Negative cash flow occurs when property expenses exceed rental income, requiring the owner to contribute additional funds.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(108, 'Investment', 'property_appreciation', 'What is property appreciation?', NULL, 'Property appreciation is the increase in a property’s value over time due to factors such as market demand, location improvements, economic growth, and limited supply.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(109, 'Investment', 'best_places_invest', 'Where is the best place to invest in real estate?', NULL, 'Good investment locations often have strong job growth, population growth, rental demand, infrastructure development, and potential for long-term appreciation.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(110, 'Investment', 'rental_income', 'How much rental income can I expect?', NULL, 'Rental income depends on location, property type, market demand, property condition, and comparable rental prices in the area.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(111, 'Investment', 'cap_rate', 'What is cap rate in real estate?', NULL, 'Capitalization rate, or cap rate, measures a property’s potential return based on its net operating income compared to its purchase price.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(112, 'Investment', 'real_estate_leverage', 'What does leverage mean in real estate investing?', NULL, 'Leverage means using borrowed money, such as a mortgage, to purchase a property. It allows investors to control a larger asset while using less personal capital.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(113, 'Investment', 'investment_down_payment', 'How much down payment is needed for an investment property?', NULL, 'Down payment requirements for investment properties vary by lender, property type, investor experience, and financing program.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(114, 'Investment', 'rental_property_vs_stock', 'Is real estate better than stocks as an investment?', NULL, 'Real estate and stocks have different risks, benefits, liquidity, and return potential. The better choice depends on your financial goals and investment strategy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(115, 'Investment', 'buy_condo_for_investment', 'Is buying a condo a good investment?', NULL, 'A condo can be a good investment depending on location, rental demand, building fees, rules, maintenance costs, and market conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(116, 'Investment', 'short_term_rental', 'Are short-term rentals a good investment?', NULL, 'Short-term rentals may generate higher income in certain markets but involve additional management, regulations, seasonal demand, and operating costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(117, 'Investment', 'vacation_property_investment', 'Should I buy a vacation property?', NULL, 'A vacation property can provide personal enjoyment and rental income, but investors should evaluate location demand, expenses, financing, and local regulations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(118, 'Investment', 'real_estate_risk', 'What are the risks of real estate investing?', NULL, 'Risks may include market changes, vacancies, unexpected repairs, financing costs, interest rate changes, tenant issues, and changes in regulations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(119, 'Investment', 'property_management_needed', 'Do I need a property manager for an investment property?', NULL, 'A property manager can help with tenant screening, rent collection, maintenance, and daily operations, especially for owners who live far away or own multiple properties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(120, 'Investment', 'investment_property_analysis', 'How do I evaluate an investment property?', NULL, 'Evaluate purchase price, rental income potential, expenses, location, condition, financing terms, future appreciation potential, and expected return.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(121, 'Investment', 'real_estate_portfolio', 'What is a real estate portfolio?', NULL, 'A real estate portfolio is a collection of properties owned by an investor to generate income, appreciation, or achieve specific financial goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(122, 'Investment', 'multiple_properties', 'How can I buy multiple investment properties?', NULL, 'Investors typically grow their portfolio by building equity, improving cash flow, maintaining strong finances, and using appropriate financing strategies.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(123, 'Investment', 'investment_property_taxes', 'What taxes apply to investment properties?', NULL, 'Tax rules vary by location and situation. Investment property owners may need to consider rental income taxes, property taxes, and potential capital gains taxes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(124, 'Investment', 'real_estate_market_timing', 'Is now a good time to invest in real estate?', NULL, 'The right time to invest depends on your financial readiness, investment goals, market conditions, property values, interest rates, and long-term strategy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(125, 'Investment', 'first_investment_property', 'What type of property is best for a first investment?', NULL, 'Many first-time investors consider properties that match their budget, have strong rental demand, manageable expenses, and potential for long-term growth.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:16', '2026-08-03 07:36:16'),
(126, 'Valuation', 'home_worth', 'How much is my home worth?', NULL, 'Your home value depends on location, property size, condition, upgrades, recent comparable sales, market conditions, and buyer demand.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(127, 'Valuation', 'free_home_valuation', 'Can I get a free home valuation?', NULL, 'Yes, a real estate professional can provide an estimated valuation using available market data and comparable property analysis.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(128, 'Valuation', 'property_value_calculation', 'How is property value calculated?', NULL, 'Property value is estimated by analyzing comparable sales, location, property features, market trends, condition, and current buyer demand.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(129, 'Valuation', 'comparative_market_analysis', 'What is a CMA?', NULL, 'A Comparative Market Analysis (CMA) is a report that compares similar properties recently sold or currently listed to help estimate a property’s market value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(130, 'Valuation', 'comparable_sales', 'What are comparable sales?', NULL, 'Comparable sales are similar properties recently sold in the same area that are used to help determine a realistic market value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(131, 'Valuation', 'increase_home_value', 'How can I increase my home value?', NULL, 'Home value can often be improved through renovations, maintenance, energy improvements, curb appeal upgrades, and improvements that match buyer preferences in your market.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(132, 'Valuation', 'renovations_value', 'Which renovations add the most value to a home?', NULL, 'Value-added renovations vary by market, but kitchens, bathrooms, energy efficiency, curb appeal, and functional improvements often attract buyers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(133, 'Valuation', 'market_value_vs_appraisal', 'What is the difference between market value and appraisal value?', NULL, 'Market value reflects what buyers may be willing to pay based on current conditions, while an appraisal is a professional valuation often used by lenders.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(134, 'Valuation', 'online_home_estimates', 'Are online home value estimates accurate?', NULL, 'Online estimates can provide a general idea, but they may not consider unique property features, recent improvements, condition, or local market changes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(135, 'Valuation', 'property_price_too_high', 'How do I know if my home price is too high?', NULL, 'Signs of overpricing may include limited buyer interest, few showings, repeated feedback about price, and longer time on the market compared with similar properties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(136, 'Valuation', 'property_price_too_low', 'Can my home be priced too low?', NULL, 'Pricing too low may reduce your potential profit, but strategic pricing can sometimes attract more buyers and create competitive offers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(137, 'Valuation', 'market_conditions', 'What are current real estate market conditions?', NULL, 'Market conditions depend on factors such as inventory levels, buyer demand, interest rates, employment trends, and local economic factors.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(138, 'Valuation', 'buyers_market', 'What is a buyer’s market?', NULL, 'A buyer’s market occurs when there are more homes available than buyers, giving buyers more negotiating power.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(139, 'Valuation', 'sellers_market', 'What is a seller’s market?', NULL, 'A seller’s market occurs when buyer demand is higher than available inventory, which may create stronger competition among buyers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(140, 'Valuation', 'housing_market_forecast', 'Will home prices go up or down?', NULL, 'Future home prices depend on many factors including interest rates, supply and demand, economic conditions, and local market trends.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(141, 'Valuation', 'property_appreciation_rate', 'How fast does a property increase in value?', NULL, 'Property appreciation rates vary by location, economic conditions, neighborhood development, demand, and market cycles.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(142, 'Valuation', 'neighborhood_value', 'How does neighborhood affect home value?', NULL, 'Neighborhood factors such as schools, transportation, amenities, safety, development, and demand can significantly influence property values.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(143, 'Valuation', 'location_importance', 'Why is location important in real estate?', NULL, 'Location affects property value because buyers consider convenience, lifestyle, accessibility, future growth, and neighborhood quality.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(144, 'Valuation', 'market_comparison', 'How do I compare my home to similar homes?', NULL, 'Compare properties based on location, size, age, condition, features, upgrades, and recent selling prices of similar homes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(145, 'Valuation', 'property_tax_value', 'Does assessed value equal market value?', NULL, 'Assessed value and market value are different. Assessed value is used for taxation purposes, while market value reflects potential selling price.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(146, 'Valuation', 'home_equity_growth', 'How can I build more home equity?', NULL, 'Home equity can grow through mortgage payments, property improvements, market appreciation, and reducing outstanding loan balances.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(147, 'Valuation', 'negative_home_equity', 'What is negative equity?', NULL, 'Negative equity occurs when the amount owed on a property is greater than its current market value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(148, 'Valuation', 'property_reassessment', 'Can my property value change over time?', NULL, 'Yes, property values change due to market conditions, improvements, neighborhood changes, economic factors, and buyer demand.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(149, 'Valuation', 'sell_price_strategy', 'How do I choose the right selling price?', NULL, 'The right selling price should balance market data, property condition, buyer demand, competition, and your financial goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(150, 'Valuation', 'investment_property_value', 'How is an investment property valued?', NULL, 'Investment properties are often evaluated using rental income, expenses, location, market conditions, comparable sales, and expected return.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:36:39', '2026-08-03 07:36:39'),
(151, 'Offers', 'how_make_offer', 'How do I make an offer on a property?', NULL, 'To make an offer, your agent prepares an offer based on the property value, market conditions, comparable sales, your budget, and your preferred terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(152, 'Offers', 'offer_price_decision', 'How much should I offer for a house?', NULL, 'The right offer depends on the asking price, market conditions, comparable sales, property condition, competition, and your negotiation strategy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(153, 'Offers', 'lowball_offer', 'Can I make a lower offer than the asking price?', NULL, 'Yes, buyers can submit offers below the asking price. The success of a lower offer depends on market conditions, seller motivation, and how the offer is structured.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(154, 'Offers', 'multiple_offers_buyer', 'What happens if there are multiple offers on a home?', NULL, 'When multiple buyers submit offers, the seller may compare price, financing strength, conditions, closing timeline, and other terms before choosing an offer.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(155, 'Offers', 'counter_offer', 'What is a counter offer?', NULL, 'A counter offer is a response from a buyer or seller that changes the terms of the original offer, such as price, conditions, or closing date.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07');
INSERT INTO `real_estate_faqs` (`id`, `category`, `intent_name`, `user_question`, `question_variations`, `answer`, `required_information`, `agent_handoff`, `keywords`, `language`, `status`, `created_at`, `updated_at`) VALUES
(156, 'Offers', 'offer_expiration', 'How long does a real estate offer remain valid?', NULL, 'The validity period depends on the terms written in the offer agreement. Offers usually include an expiration date and time.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(157, 'Offers', 'offer_rejected', 'What happens if my offer is rejected?', NULL, 'If your offer is rejected, you may choose to submit another offer, negotiate if possible, or continue searching for other properties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(158, 'Offers', 'earnest_money', 'What is earnest money?', NULL, 'Earnest money is a deposit made by a buyer to show commitment to purchasing a property. The amount and rules vary by location and agreement terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(159, 'Offers', 'contingency', 'What is a contingency in real estate?', NULL, 'A contingency is a condition that must be satisfied before a transaction can proceed, such as financing approval, inspection results, or selling an existing home.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(160, 'Offers', 'inspection_contingency', 'What is an inspection contingency?', NULL, 'An inspection contingency allows a buyer to inspect the property and may provide options depending on the findings and contract terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(161, 'Offers', 'financing_contingency', 'What is a financing contingency?', NULL, 'A financing contingency protects the buyer if they are unable to obtain mortgage approval under the agreed terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(162, 'Offers', 'appraisal_contingency', 'What is an appraisal contingency?', NULL, 'An appraisal contingency addresses situations where the appraised value is lower than the purchase price and may allow negotiation or other options.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(163, 'Offers', 'closing_date', 'Can the buyer and seller negotiate the closing date?', NULL, 'Yes, the closing date is usually a negotiable part of the purchase agreement and depends on both parties’ needs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(164, 'Offers', 'contract_acceptance', 'When does a real estate contract become official?', NULL, 'A contract becomes official when all parties agree to the terms, sign the required documents, and all necessary conditions are satisfied according to local laws.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(165, 'Offers', 'changing_offer', 'Can I change my offer after submitting it?', NULL, 'Changes may be possible depending on whether the seller has accepted the offer and the status of the contract. Your agent can explain your options.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(166, 'Offers', 'seller_accept_offer', 'How does a seller choose an offer?', NULL, 'Sellers typically consider price, financing reliability, contingencies, closing timeline, and overall terms rather than only the highest price.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(167, 'Offers', 'highest_offer_not_best', 'Is the highest offer always the best offer?', NULL, 'No. A lower offer with stronger financing, fewer conditions, and a better closing timeline may be more attractive to a seller.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(168, 'Offers', 'contract_cancellation', 'Can a real estate contract be cancelled?', NULL, 'Cancellation depends on the contract terms, contingencies, legal requirements, and circumstances of the transaction.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(169, 'Offers', 'buyer_back_out', 'Can a buyer back out after making an offer?', NULL, 'Whether a buyer can withdraw depends on the contract terms, applicable contingencies, and local regulations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(170, 'Offers', 'seller_back_out', 'Can a seller cancel a contract after accepting an offer?', NULL, 'After accepting an offer, seller options may be limited and depend on the contract terms and applicable laws.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(171, 'Offers', 'negotiating_repairs', 'Can I negotiate repairs after the inspection?', NULL, 'Yes, buyers and sellers may negotiate repairs, credits, or price adjustments depending on the inspection results and contract terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(172, 'Offers', 'real_estate_attorney', 'Do I need a lawyer for a real estate contract?', NULL, 'Requirements vary by location. Some areas require legal involvement while others allow transactions through agents, title companies, or other professionals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(173, 'Offers', 'contract_review', 'Should I review the contract before signing?', NULL, 'Yes, all parties should carefully review contract terms, obligations, deadlines, and conditions before signing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(174, 'Offers', 'offer_strength', 'How can I make my offer stronger?', NULL, 'You can strengthen an offer by getting pre-approved, offering competitive terms, minimizing unnecessary conditions, and providing a clear timeline.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(175, 'Offers', 'seller_negotiation_strategy', 'How can sellers negotiate better terms?', NULL, 'Sellers can improve negotiations by pricing strategically, understanding market conditions, evaluating buyer strength, and working with an experienced agent.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:07', '2026-08-03 07:37:07'),
(176, 'Closing', 'what_is_closing', 'What is the closing process?', NULL, 'Closing is the final stage of a real estate transaction where documents are signed, funds are transferred, ownership is officially transferred, and the buyer receives the property keys.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(177, 'Closing', 'closing_day', 'What happens on closing day?', NULL, 'On closing day, buyers and sellers complete required paperwork, final payments are processed, ownership documents are finalized, and the transaction is completed.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(178, 'Closing', 'closing_documents', 'What documents are needed for closing?', NULL, 'Common closing documents may include identification, purchase agreement, loan documents, title documents, insurance information, and financial records required by the parties involved.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(179, 'Closing', 'closing_costs_buyer', 'What closing costs does a buyer pay?', NULL, 'Buyer closing costs may include lender fees, appraisal fees, title services, insurance, taxes, recording fees, and other transaction-related expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(180, 'Closing', 'closing_costs_seller', 'What closing costs does a seller pay?', NULL, 'Seller closing costs may include agent fees, taxes, title-related costs, legal fees, and other expenses required to complete the sale.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(181, 'Closing', 'final_walkthrough', 'What is a final walkthrough?', NULL, 'A final walkthrough allows the buyer to inspect the property shortly before closing to confirm its condition and verify agreed repairs have been completed.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(182, 'Closing', 'when_get_keys', 'When do I get the keys after buying a home?', NULL, 'Keys are typically provided after the closing process is completed and ownership has officially transferred according to the purchase agreement.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(183, 'Closing', 'title_search', 'What is a title search?', NULL, 'A title search reviews public records to confirm property ownership and identify potential issues such as liens, claims, or ownership problems.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(184, 'Closing', 'title_insurance', 'What is title insurance?', NULL, 'Title insurance helps protect buyers and lenders against certain ownership-related issues that may be discovered after the purchase.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(185, 'Closing', 'property_deed', 'What is a property deed?', NULL, 'A deed is a legal document that transfers ownership of real estate from one party to another.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(186, 'Closing', 'home_inspection_process', 'What happens during a home inspection?', NULL, 'A home inspector evaluates the property’s condition, including major systems, structure, safety issues, and potential repairs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(187, 'Closing', 'inspection_cost', 'Who pays for the home inspection?', NULL, 'Inspection payment responsibilities vary, but buyers commonly arrange and pay for inspections as part of the purchase process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(188, 'Closing', 'inspection_fail', 'What happens if a home inspection finds problems?', NULL, 'If issues are discovered, buyers may negotiate repairs, request credits, adjust terms, or make decisions based on the contract and inspection results.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(189, 'Closing', 'appraisal_process', 'How does the home appraisal process work?', NULL, 'An appraiser evaluates the property using factors such as location, condition, size, features, and comparable sales to determine estimated market value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(190, 'Closing', 'low_appraisal', 'What happens if the appraisal is lower than the purchase price?', NULL, 'A low appraisal may require renegotiation, additional buyer funds, lender adjustments, or other solutions depending on the agreement.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(191, 'Closing', 'who_orders_appraisal', 'Who orders the home appraisal?', NULL, 'Typically, the lender orders the appraisal during the mortgage process to confirm the property value supports the loan amount.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(192, 'Closing', 'home_insurance_requirement', 'Do I need homeowners insurance before closing?', NULL, 'Many lenders require homeowners insurance before completing a financed home purchase. Coverage requirements vary by lender and location.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(193, 'Closing', 'mortgage_closing', 'When is my mortgage finalized?', NULL, 'Mortgage finalization usually occurs after lender approval, document review, appraisal completion, and satisfaction of all loan conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(194, 'Closing', 'closing_delay', 'Why can a real estate closing be delayed?', NULL, 'Closings may be delayed due to financing issues, missing documents, title problems, appraisal concerns, inspection negotiations, or other transaction issues.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(195, 'Closing', 'closing_attendees', 'Who attends the closing?', NULL, 'Closing participants vary by location but may include buyers, sellers, agents, lenders, attorneys, title representatives, and other professionals involved in the transaction.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(196, 'Closing', 'electronic_closing', 'Can real estate closing be completed online?', NULL, 'Some locations and transactions allow electronic or remote closing options depending on local laws, lender requirements, and available technology.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(197, 'Closing', 'ownership_transfer', 'When does ownership officially transfer?', NULL, 'Ownership usually transfers after closing documents are signed, funds are delivered, and the deed or required documents are officially recorded.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(198, 'Closing', 'recording_deed', 'What does recording a deed mean?', NULL, 'Recording a deed means officially filing the ownership transfer with the appropriate government office to create a public record.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(199, 'Closing', 'moving_after_closing', 'When can I move into my new home?', NULL, 'Move-in timing depends on the closing completion, possession agreement, and any arrangements made between the buyer and seller.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(200, 'Closing', 'post_closing_questions', 'What should I do after buying a home?', NULL, 'After closing, update your address, set up utilities, review insurance coverage, maintain important documents, and plan regular property maintenance.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:29', '2026-08-03 07:37:29'),
(201, 'Homeownership', 'first_home_purchase', 'What should I know before buying my first home?', NULL, 'Before buying your first home, understand your budget, financing options, ongoing ownership costs, neighborhood preferences, and the responsibilities of maintaining a property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(202, 'Homeownership', 'new_homeowner_first_steps', 'What should I do after buying my first home?', NULL, 'After purchasing a home, set up utilities, change your address, review insurance coverage, organize documents, learn your home systems, and create a maintenance plan.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(203, 'Homeownership', 'home_maintenance', 'How often should I maintain my home?', NULL, 'Regular maintenance should be performed throughout the year. Tasks may include checking systems, cleaning, inspecting for issues, and completing preventative repairs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(204, 'Homeownership', 'home_maintenance_cost', 'How much should I budget for home maintenance?', NULL, 'Home maintenance costs vary by property age, size, condition, and location. Planning a regular maintenance budget can help manage unexpected repairs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(205, 'Homeownership', 'property_taxes', 'What are property taxes?', NULL, 'Property taxes are payments made to local governments based on the assessed value of a property. They help fund public services and vary by location.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(206, 'Homeownership', 'property_tax_payment', 'How do I pay property taxes?', NULL, 'Property tax payment methods depend on local rules. Some homeowners pay directly while others may have taxes included in their mortgage payment through an escrow account.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(207, 'Homeownership', 'homeowners_insurance', 'What is homeowners insurance?', NULL, 'Homeowners insurance provides protection against certain property damage, losses, and liability risks. Coverage options vary by policy and provider.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(208, 'Homeownership', 'insurance_requirement', 'Do I need homeowners insurance?', NULL, 'Homeowners insurance is strongly recommended and is often required by mortgage lenders when financing a property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(209, 'Homeownership', 'home_warranty', 'What is a home warranty?', NULL, 'A home warranty is a service agreement that may help cover repairs or replacements of certain home systems and appliances depending on the plan terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(210, 'Homeownership', 'utility_setup', 'How do I set up utilities after buying a home?', NULL, 'Contact local utility providers to transfer or establish services such as electricity, water, gas, internet, and other required services before moving in.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(211, 'Homeownership', 'change_address', 'When should I change my address after moving?', NULL, 'Update your address with government agencies, financial institutions, employers, subscriptions, insurance providers, and other important contacts after moving.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(212, 'Homeownership', 'moving_checklist', 'What should I do before moving into my new home?', NULL, 'Before moving, schedule movers if needed, transfer utilities, clean the property, inspect important systems, update your address, and prepare essential items.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(213, 'Homeownership', 'home_security', 'How can I improve my home security?', NULL, 'Home security improvements may include better locks, lighting, alarm systems, cameras, smart devices, and maintaining good neighborhood awareness.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(214, 'Homeownership', 'energy_efficiency', 'How can I make my home more energy efficient?', NULL, 'Energy efficiency improvements may include insulation, efficient appliances, smart thermostats, sealing drafts, and upgrading windows or systems.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(215, 'Homeownership', 'home_improvement', 'What home improvements add value?', NULL, 'Improvements that improve functionality, appearance, energy efficiency, and buyer appeal may increase home value depending on the market.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(216, 'Homeownership', 'renovation_budget', 'How should I budget for home renovations?', NULL, 'Create a renovation budget by estimating project costs, prioritizing important improvements, planning for unexpected expenses, and comparing contractor estimates.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(217, 'Homeownership', 'contractor_selection', 'How do I choose a contractor?', NULL, 'Choose contractors by reviewing experience, references, licensing requirements, insurance coverage, estimates, and written agreements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(218, 'Homeownership', 'home_equity_explained', 'How does home equity work?', NULL, 'Home equity is the portion of your property you own after subtracting your remaining mortgage balance from the current property value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(219, 'Homeownership', 'building_equity', 'How can I build equity faster?', NULL, 'Equity can grow through regular mortgage payments, additional principal payments if allowed, property improvements, and increases in property value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(220, 'Homeownership', 'refinance_home', 'Should I refinance my home?', NULL, 'Refinancing may be beneficial depending on interest rates, your financial goals, loan terms, and costs involved. A mortgage professional can help evaluate your options.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(221, 'Homeownership', 'property_records', 'What home documents should I keep?', NULL, 'Important documents include purchase agreements, deed records, mortgage documents, insurance policies, warranties, repair records, and improvement receipts.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(222, 'Homeownership', 'home_inventory', 'Should I create a home inventory?', NULL, 'A home inventory can help document your belongings for insurance purposes and make it easier to track valuable items.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(223, 'Homeownership', 'selling_future', 'How soon can I sell my home after buying?', NULL, 'You can generally sell when you choose, but financial considerations such as transaction costs, market conditions, and mortgage obligations should be evaluated.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(224, 'Homeownership', 'renting_out_home', 'Can I rent out my home after buying it?', NULL, 'Whether you can rent your home depends on mortgage terms, local regulations, insurance requirements, and any community restrictions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(225, 'Homeownership', 'homeownership_costs', 'What are the ongoing costs of owning a home?', NULL, 'Ongoing costs may include mortgage payments, property taxes, insurance, utilities, maintenance, repairs, and possible homeowner association fees.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:37:58', '2026-08-03 07:37:58'),
(226, 'Agent Services', 'what_does_agent_do', 'What does a real estate agent do?', NULL, 'A real estate agent helps buyers and sellers navigate transactions by providing market information, arranging property searches or listings, negotiating terms, managing paperwork, and guiding clients through closing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(227, 'Agent Services', 'why_use_agent', 'Why should I use a real estate agent?', NULL, 'A real estate agent can provide market expertise, negotiation support, access to property information, transaction guidance, and assistance with complex paperwork.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(228, 'Agent Services', 'choose_real_estate_agent', 'How do I choose the right real estate agent?', NULL, 'Choose an agent based on local market knowledge, experience, communication style, reviews, negotiation skills, and understanding of your goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(229, 'Agent Services', 'buyer_agent_role', 'What does a buyer’s agent do?', NULL, 'A buyer’s agent helps clients find suitable properties, analyze market value, prepare offers, negotiate terms, coordinate inspections, and guide buyers through closing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(230, 'Agent Services', 'seller_agent_role', 'What does a listing agent do?', NULL, 'A listing agent helps sellers price, market, negotiate, and complete the sale of their property while representing the seller’s interests.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(231, 'Agent Services', 'agent_commission', 'How do real estate agents get paid?', NULL, 'Real estate agents are typically compensated through commissions or fees based on agreements between the parties involved. Payment structures vary by location and transaction type.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(232, 'Agent Services', 'agent_fee_buyer', 'Does a buyer have to pay a real estate agent?', NULL, 'Agent compensation arrangements vary depending on location, agreements, and transaction structure. Your agent can explain the costs and terms involved.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(233, 'Agent Services', 'agent_consultation', 'Can I talk to a real estate agent before buying?', NULL, 'Yes, speaking with an agent early can help you understand the market, define your goals, and prepare for the buying process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(234, 'Agent Services', 'agent_market_knowledge', 'Why is local market knowledge important?', NULL, 'Local market knowledge helps an agent provide accurate pricing guidance, identify opportunities, understand neighborhoods, and negotiate effectively.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(235, 'Agent Services', 'agent_property_access', 'Can agents see properties that are not publicly listed?', NULL, 'Agents may have access to professional listing networks and industry resources that can provide additional property information depending on the market.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(236, 'Agent Services', 'agent_property_search', 'Can an agent help me find a specific type of property?', NULL, 'Yes, agents can help search based on criteria such as location, budget, property type, size, features, and lifestyle needs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(237, 'Agent Services', 'agent_home_listing', 'How do I list my home with an agent?', NULL, 'The listing process usually includes a consultation, property evaluation, pricing strategy, marketing plan, listing agreement, and preparation of the property for buyers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(238, 'Agent Services', 'agent_marketing_plan', 'How will an agent market my property?', NULL, 'Marketing strategies may include online listings, professional photography, virtual tours, social media, advertising, open houses, and buyer networks.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(239, 'Agent Services', 'agent_negotiation', 'Can a real estate agent negotiate for me?', NULL, 'Yes, agents help negotiate price, terms, conditions, repairs, timelines, and other important transaction details.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(240, 'Agent Services', 'real_estate_advice', 'Can you give me real estate advice?', NULL, 'I can provide general real estate information and guidance. For decisions involving your specific financial or legal situation, consult qualified professionals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(241, 'Agent Services', 'real_estate_market_update', 'Can you provide real estate market updates?', NULL, 'Yes, a real estate professional can provide information about local market trends, inventory, pricing activity, and buyer or seller conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(242, 'Agent Services', 'property_viewing_agent', 'Can an agent arrange property viewings?', NULL, 'Yes, agents can schedule property tours, coordinate access, and help you evaluate homes during viewings.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(243, 'Agent Services', 'agent_response_time', 'How quickly will a real estate agent respond?', NULL, 'Response times vary by agent and communication method. A good agent should establish clear expectations for communication.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(244, 'Agent Services', 'working_with_multiple_agents', 'Can I work with multiple real estate agents?', NULL, 'Rules and agreements vary depending on location and representation agreements. Discuss expectations with your agent before working with others.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(245, 'Agent Services', 'exclusive_agreement', 'What is an exclusive buyer agreement?', NULL, 'An exclusive buyer agreement is a contract where a buyer agrees to work with a specific agent under defined terms for a certain period.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(246, 'Agent Services', 'real_estate_agent_license', 'Are real estate agents licensed?', NULL, 'Real estate licensing requirements vary by location. Licensed agents must generally meet education, examination, and regulatory requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(247, 'Agent Services', 'agent_experience', 'How important is an agent’s experience?', NULL, 'Experience can help an agent understand market conditions, handle negotiations, solve transaction issues, and provide better guidance.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(248, 'Agent Services', 'agent_relocation_help', 'Can a real estate agent help if I am moving to another city?', NULL, 'Yes, many agents assist with relocation by providing market information, property searches, neighborhood guidance, and connections to local services.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(249, 'Agent Services', 'agent_investor_help', 'Can an agent help real estate investors?', NULL, 'Yes, agents can assist investors by identifying opportunities, analyzing properties, understanding markets, and supporting purchase transactions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(250, 'Agent Services', 'contact_agent', 'How do I contact a real estate agent?', NULL, 'You can contact a real estate agent through phone, email, website forms, messaging platforms, or scheduling a consultation.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:23', '2026-08-03 07:38:23'),
(251, 'Commercial', 'what_is_commercial_real_estate', 'What is commercial real estate?', NULL, 'Commercial real estate includes properties used for business purposes, such as offices, retail spaces, warehouses, industrial buildings, and investment properties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(252, 'Commercial', 'buy_commercial_property', 'How do I buy a commercial property?', NULL, 'Buying commercial property involves defining your business needs, evaluating locations, analyzing financials, arranging financing, conducting due diligence, negotiating terms, and completing the transaction.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(253, 'Commercial', 'commercial_vs_residential', 'What is the difference between commercial and residential real estate?', NULL, 'Residential real estate is primarily used for homes, while commercial real estate is used for business activities, income generation, and investment purposes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(254, 'Commercial', 'commercial_property_types', 'What types of commercial properties are available?', NULL, 'Commercial properties include office buildings, retail stores, restaurants, warehouses, industrial facilities, medical buildings, mixed-use properties, and land for development.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(255, 'Commercial', 'commercial_property_investment', 'Is commercial real estate a good investment?', NULL, 'Commercial real estate can provide rental income and long-term value growth, but investors should consider market conditions, tenant risk, expenses, financing, and location factors.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(256, 'Commercial', 'commercial_property_value', 'How is commercial property valued?', NULL, 'Commercial property value is often based on income potential, comparable sales, location, property condition, expenses, market demand, and investment returns.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(257, 'Commercial', 'commercial_cap_rate', 'What is cap rate for commercial real estate?', NULL, 'Cap rate measures the potential return of a commercial property by comparing net operating income to the property value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(258, 'Commercial', 'commercial_loan', 'How do commercial real estate loans work?', NULL, 'Commercial loans are financing options designed for business and investment properties. Requirements may include property analysis, borrower qualifications, income verification, and financial documentation.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(259, 'Commercial', 'commercial_down_payment', 'How much down payment is needed for commercial property?', NULL, 'Commercial property down payment requirements vary based on lender requirements, property type, borrower qualifications, and investment strategy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(260, 'Commercial', 'lease_commercial_space', 'How do I lease commercial space?', NULL, 'Leasing commercial space involves identifying business needs, finding suitable properties, reviewing lease terms, negotiating conditions, and signing a commercial lease agreement.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(261, 'Commercial', 'office_space_search', 'Can you help me find office space?', NULL, 'Yes, a commercial real estate professional can help identify office spaces based on location, size, budget, amenities, and business requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(262, 'Commercial', 'retail_space', 'How do I find a retail location for my business?', NULL, 'Choosing a retail location involves evaluating customer traffic, demographics, visibility, competition, lease costs, accessibility, and future growth potential.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(263, 'Commercial', 'warehouse_space', 'How do I find warehouse space?', NULL, 'Warehouse selection depends on factors such as size, loading access, ceiling height, storage needs, location, transportation access, and zoning requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(264, 'Commercial', 'commercial_lease_terms', 'What are common commercial lease terms?', NULL, 'Commercial lease terms may include rent amount, lease duration, renewal options, maintenance responsibilities, operating expenses, and permitted business activities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(265, 'Commercial', 'triple_net_lease', 'What is a triple net lease?', NULL, 'A triple net lease is a commercial lease where the tenant may be responsible for property expenses such as taxes, insurance, and maintenance in addition to rent.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(266, 'Commercial', 'commercial_rent_calculation', 'How is commercial rent calculated?', NULL, 'Commercial rent may be calculated based on square footage, location, property type, market rates, lease structure, and additional operating expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(267, 'Commercial', 'zoning_requirements', 'What is commercial zoning?', NULL, 'Commercial zoning determines how a property can be used for business purposes and may include restrictions on activities, building requirements, and permitted uses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(268, 'Commercial', 'commercial_due_diligence', 'What is commercial real estate due diligence?', NULL, 'Due diligence involves reviewing property documents, financial records, leases, inspections, zoning, environmental issues, and other factors before completing a purchase.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(269, 'Commercial', 'commercial_property_management', 'What is commercial property management?', NULL, 'Commercial property management includes handling tenants, maintenance, rent collection, lease administration, and daily operations of commercial properties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(270, 'Commercial', 'commercial_tenant_screening', 'How are commercial tenants evaluated?', NULL, 'Commercial tenant evaluation may include reviewing business history, financial statements, creditworthiness, business plans, and rental references.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(271, 'Commercial', 'commercial_real_estate_agent', 'Why use a commercial real estate agent?', NULL, 'A commercial real estate agent provides market knowledge, property searches, negotiation assistance, transaction guidance, and industry expertise.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(272, 'Commercial', 'business_location_analysis', 'How do I choose the right location for my business?', NULL, 'Location selection should consider customer access, competition, visibility, costs, workforce availability, transportation, and future growth opportunities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(273, 'Commercial', 'sell_commercial_property', 'How do I sell a commercial property?', NULL, 'Selling commercial property involves valuation, marketing, finding qualified buyers, negotiating terms, completing due diligence, and closing the transaction.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(274, 'Commercial', 'commercial_property_market', 'What affects the commercial real estate market?', NULL, 'Commercial markets are affected by economic conditions, interest rates, business growth, employment trends, supply and demand, and local development.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(275, 'Commercial', 'commercial_investment_risk', 'What are the risks of commercial real estate investing?', NULL, 'Commercial investment risks may include vacancies, economic changes, tenant issues, financing costs, market fluctuations, and unexpected property expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:38:51', '2026-08-03 07:38:51'),
(276, 'Relocation', 'relocation_help', 'Can a real estate agent help me relocate?', NULL, 'Yes, a real estate agent can help with relocation by providing market information, neighborhood guidance, property searches, virtual tours, and connections to local services.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(277, 'Relocation', 'moving_to_new_city', 'I am moving to a new city. Where should I start?', NULL, 'Start by researching neighborhoods, understanding your budget, reviewing housing options, and connecting with a local real estate professional who understands the area.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(278, 'Relocation', 'out_of_state_buying', 'Can I buy a home from another state?', NULL, 'Yes, many buyers purchase homes remotely. A real estate agent can help with virtual tours, local market information, inspections, paperwork, and coordination.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(279, 'Relocation', 'remote_home_search', 'How can I search for a home remotely?', NULL, 'Remote buyers can use online listings, video tours, virtual meetings, digital documents, and local agent support to complete the home search process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(280, 'Relocation', 'virtual_tour', 'Can I view homes through virtual tours?', NULL, 'Yes, many properties offer virtual tours, video walkthroughs, and online viewing options to help buyers evaluate homes remotely.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(281, 'Relocation', 'choose_relocation_area', 'How do I choose the right area when relocating?', NULL, 'Consider employment opportunities, schools, commute times, cost of living, amenities, safety, lifestyle preferences, and future growth potential.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(282, 'Relocation', 'relocation_budget', 'How much should I budget when relocating?', NULL, 'Consider home costs, moving expenses, temporary housing, transportation, storage, utility setup, taxes, insurance, and other transition costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(283, 'Relocation', 'moving_costs', 'How much does moving cost?', NULL, 'Moving costs depend on distance, amount of belongings, moving services, timing, storage needs, and special requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(284, 'Relocation', 'relocation_agent_network', 'Can my agent help me find an agent in another city?', NULL, 'Many real estate professionals have networks and can help connect you with trusted agents in other locations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(285, 'Relocation', 'buy_before_move', 'Should I buy a home before moving?', NULL, 'Buying before moving depends on your financial situation, market conditions, timing, and confidence in the new location.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(286, 'Relocation', 'rent_before_buy', 'Should I rent first when relocating?', NULL, 'Renting first can allow you to learn the area, understand neighborhoods, and make a more informed buying decision.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(287, 'Relocation', 'job_relocation_home', 'I am relocating for work. Can you help me find a home?', NULL, 'Yes, an agent can help identify homes that match your work location, commute preferences, budget, and lifestyle needs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(288, 'Relocation', 'school_area_search', 'How do I find a home near good schools?', NULL, 'An agent can help you research neighborhoods and provide property information, while official school resources should be reviewed for current school details.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(289, 'Relocation', 'commute_location', 'How important is commute when choosing a home?', NULL, 'Commute time can significantly affect daily lifestyle, transportation costs, and neighborhood choices, so it should be considered when selecting a location.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(290, 'Relocation', 'moving_checklist', 'What should I do before relocating?', NULL, 'Create a moving plan, organize finances, research your new area, arrange housing, schedule movers, transfer services, and update important records.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(291, 'Relocation', 'relocation_timeline', 'How far in advance should I plan a relocation?', NULL, 'Planning time depends on distance, housing needs, work deadlines, and personal circumstances. Starting early helps reduce stress and improve options.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(292, 'Relocation', 'temporary_housing', 'Should I use temporary housing during relocation?', NULL, 'Temporary housing can be helpful when you need time to search for a permanent home or are still learning the new area.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(293, 'Relocation', 'relocation_family_move', 'What should families consider when relocating?', NULL, 'Families should consider schools, neighborhood environment, healthcare access, activities, commute, housing needs, and community resources.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(294, 'Relocation', 'pet_relocation', 'What should I consider when moving with pets?', NULL, 'Plan for transportation, pet-friendly housing, veterinary records, travel requirements, and adjusting pets to the new environment.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(295, 'Relocation', 'moving_documents', 'What documents should I organize before moving?', NULL, 'Important documents may include identification, financial records, medical records, insurance information, housing documents, and employment paperwork.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(296, 'Relocation', 'relocation_market_research', 'How do I research a new real estate market?', NULL, 'Research home prices, inventory levels, neighborhoods, taxes, insurance costs, employment trends, and local amenities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(297, 'Relocation', 'buying_sight_unseen', 'Can I buy a home without visiting it?', NULL, 'Some buyers purchase homes without visiting in person, but it is important to use inspections, virtual tours, trusted professionals, and careful research.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(298, 'Relocation', 'relocation_closing', 'Can I complete closing if I live far away?', NULL, 'Many locations offer remote closing options depending on local regulations, title companies, lenders, and transaction requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(299, 'Relocation', 'moving_services', 'Can you recommend moving services?', NULL, 'A real estate professional may be able to provide general guidance or connect you with local moving resources, depending on available services.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(300, 'Relocation', 'settling_new_home', 'How can I settle into my new home quickly?', NULL, 'Set up essential services, organize important rooms first, learn your neighborhood, update records, and establish local connections.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:16', '2026-08-03 07:39:16'),
(301, 'Property Management', 'what_is_property_management', 'What is property management?', NULL, 'Property management involves handling rental property operations including tenant communication, rent collection, maintenance coordination, inspections, and administrative tasks.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(302, 'Property Management', 'hire_property_manager', 'Should I hire a property manager?', NULL, 'A property manager can be helpful if you own multiple properties, live far away, have limited time, or want professional assistance managing tenants and maintenance.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(303, 'Property Management', 'property_manager_cost', 'How much does a property manager cost?', NULL, 'Property management fees vary depending on location, property type, services provided, and the agreement between the owner and manager.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(304, 'Property Management', 'landlord_find_tenants', 'How can I find good tenants?', NULL, 'Finding good tenants usually involves effective marketing, application screening, income verification, credit checks, reference checks, and following applicable laws.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(305, 'Property Management', 'tenant_screening_process', 'What is the tenant screening process?', NULL, 'Tenant screening may include reviewing rental applications, income verification, credit history, rental references, and other qualifications.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(306, 'Property Management', 'collect_rent', 'How should I collect rent from tenants?', NULL, 'Rent collection methods depend on the lease agreement and local practices. Many landlords use online payment systems, bank transfers, or property management platforms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(307, 'Property Management', 'late_rent', 'What should I do if a tenant does not pay rent?', NULL, 'If rent is unpaid, follow the lease agreement and applicable local regulations. Communication, notices, payment arrangements, or legal procedures may be required.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(308, 'Property Management', 'tenant_maintenance_request', 'How should landlords handle maintenance requests?', NULL, 'Landlords should respond promptly, assess the issue, arrange qualified repairs when needed, and keep records of maintenance activities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37');
INSERT INTO `real_estate_faqs` (`id`, `category`, `intent_name`, `user_question`, `question_variations`, `answer`, `required_information`, `agent_handoff`, `keywords`, `language`, `status`, `created_at`, `updated_at`) VALUES
(309, 'Property Management', 'landlord_repairs', 'Who is responsible for property repairs?', NULL, 'Responsibility for repairs depends on the lease agreement, property condition, and local laws. Landlords typically handle major property maintenance responsibilities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(310, 'Property Management', 'rental_property_inspection', 'How often should rental properties be inspected?', NULL, 'Inspection frequency depends on local laws, lease terms, property type, and the purpose of the inspection. Proper notice is generally required.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(311, 'Property Management', 'increase_rent', 'Can I increase rent for my rental property?', NULL, 'Rent increases depend on lease terms, local regulations, market conditions, and applicable notice requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(312, 'Property Management', 'vacancy_period', 'How can I reduce rental vacancy time?', NULL, 'Reducing vacancy involves competitive pricing, good marketing, property maintenance, quick responses, and providing a positive tenant experience.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(313, 'Property Management', 'tenant_turnover', 'How can I manage tenant turnover?', NULL, 'Effective turnover management includes timely inspections, repairs, cleaning, marketing preparation, and efficient tenant screening.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(314, 'Property Management', 'lease_renewal', 'How do lease renewals work?', NULL, 'Lease renewals allow landlords and tenants to continue a rental agreement under updated or existing terms depending on their agreement.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(315, 'Property Management', 'tenant_eviction', 'How does the eviction process work?', NULL, 'Eviction procedures vary by location and generally require following legal notice requirements and court procedures. Landlords should follow applicable laws.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(316, 'Property Management', 'rental_property_accounting', 'How should I track rental property finances?', NULL, 'Landlords should maintain records of rental income, expenses, repairs, taxes, insurance, mortgage payments, and other property-related costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(317, 'Property Management', 'rental_property_profit', 'How do I calculate rental property profit?', NULL, 'Rental property profit is calculated by comparing rental income against operating expenses, financing costs, taxes, maintenance, and other expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(318, 'Property Management', 'landlord_insurance', 'Do landlords need special insurance?', NULL, 'Landlord insurance is designed for rental properties and may provide coverage different from standard homeowner insurance policies.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(319, 'Property Management', 'tenant_complaints', 'How should landlords handle tenant complaints?', NULL, 'Landlords should listen, communicate clearly, document issues, respond professionally, and address valid concerns according to lease terms and regulations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(320, 'Property Management', 'remote_landlord', 'Can I manage a rental property from another city?', NULL, 'Yes, remote ownership is possible with technology, reliable vendors, and professional property management support.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(321, 'Property Management', 'rental_property_marketing', 'How do I advertise my rental property?', NULL, 'Rental properties can be marketed through online listings, rental platforms, professional photos, social media, signs, and local networks.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(322, 'Property Management', 'tenant_retention', 'How can I keep good tenants longer?', NULL, 'Good tenant retention comes from fair communication, timely maintenance, reasonable policies, and creating a positive rental experience.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(323, 'Property Management', 'property_manager_services', 'What services does a property manager provide?', NULL, 'Services may include tenant placement, rent collection, maintenance coordination, inspections, lease administration, and financial reporting.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(324, 'Property Management', 'landlord_legal_requirements', 'What legal responsibilities do landlords have?', NULL, 'Landlord responsibilities vary by location but commonly include maintaining safe housing conditions, following rental laws, respecting tenant rights, and honoring lease agreements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(325, 'Property Management', 'rental_property_management_benefit', 'What are the benefits of professional property management?', NULL, 'Professional management can save time, improve tenant relationships, reduce operational issues, and help owners manage rental properties more efficiently.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:39:37', '2026-08-03 07:39:37'),
(326, 'Legal', 'purchase_agreement', 'What is a purchase agreement?', NULL, 'A purchase agreement is a legal contract between a buyer and seller that outlines the terms and conditions of a real estate transaction.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(327, 'Legal', 'real_estate_contract', 'What is a real estate contract?', NULL, 'A real estate contract is a legally binding agreement that defines the rights, responsibilities, terms, and obligations of the parties involved in a property transaction.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(328, 'Legal', 'property_disclosure', 'What is a property disclosure statement?', NULL, 'A property disclosure statement provides information about known conditions, defects, or issues with a property that may affect a buyer’s decision.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(329, 'Legal', 'seller_disclosures', 'What disclosures must a seller provide?', NULL, 'Disclosure requirements vary by location, but sellers are generally required to disclose known material issues affecting the property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(330, 'Legal', 'title_issue', 'What are title issues in real estate?', NULL, 'Title issues are problems related to property ownership records, such as liens, claims, ownership disputes, or recording errors.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(331, 'Legal', 'clear_title', 'What does clear title mean?', NULL, 'A clear title means the property ownership is free from unresolved claims, liens, or legal issues that could affect transfer of ownership.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(332, 'Legal', 'property_lien', 'What is a property lien?', NULL, 'A lien is a legal claim against a property that may need to be resolved before ownership can be transferred.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(333, 'Legal', 'ownership_types', 'What are different types of property ownership?', NULL, 'Property ownership types vary by location and may include individual ownership, joint ownership, community ownership, trusts, corporations, or other legal structures.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(334, 'Legal', 'joint_ownership', 'What is joint ownership of property?', NULL, 'Joint ownership means two or more people share ownership rights and responsibilities for a property according to the ownership agreement.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(335, 'Legal', 'property_deed_transfer', 'How is property ownership transferred?', NULL, 'Property ownership is transferred through legal documents such as a deed, which must be properly signed and recorded according to local requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(336, 'Legal', 'quitclaim_deed', 'What is a quitclaim deed?', NULL, 'A quitclaim deed transfers whatever ownership interest a person may have in a property but does not provide guarantees about ownership rights.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(337, 'Legal', 'warranty_deed', 'What is a warranty deed?', NULL, 'A warranty deed provides certain guarantees from the seller regarding ownership rights and title transfer, depending on local laws.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(338, 'Legal', 'power_of_attorney_real_estate', 'Can someone buy or sell property on my behalf?', NULL, 'In some situations, a person may authorize another individual to act on their behalf through a legal power of attorney, subject to applicable requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(339, 'Legal', 'real_estate_attorney_role', 'What does a real estate attorney do?', NULL, 'A real estate attorney can help review contracts, resolve legal issues, handle documents, and provide legal advice related to property transactions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(340, 'Legal', 'need_attorney_closing', 'Do I need an attorney for closing?', NULL, 'Whether an attorney is required depends on location, transaction type, and local regulations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(341, 'Legal', 'homeowners_association', 'What is a homeowners association (HOA)?', NULL, 'An HOA is an organization that manages shared community rules, amenities, and fees for certain residential communities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(342, 'Legal', 'hoa_fees', 'What are HOA fees?', NULL, 'HOA fees are payments made by property owners to support community maintenance, services, amenities, and shared expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(343, 'Legal', 'hoa_rules', 'Can an HOA restrict what I do with my property?', NULL, 'HOA rules may include restrictions regarding property appearance, renovations, rentals, pets, and other activities depending on governing documents.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(344, 'Legal', 'property_zoning', 'What is zoning and why does it matter?', NULL, 'Zoning determines how land and properties can be used, including residential, commercial, industrial, or mixed-use purposes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(345, 'Legal', 'property_permits', 'Do I need permits for home improvements?', NULL, 'Many renovations require permits depending on the type of work, location, and local building regulations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(346, 'Legal', 'boundary_survey', 'What is a property survey?', NULL, 'A property survey identifies boundaries, measurements, and features of a property to help confirm ownership limits.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(347, 'Legal', 'easement', 'What is an easement on a property?', NULL, 'An easement gives another party certain rights to use part of a property for a specific purpose, such as access or utilities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(348, 'Legal', 'property_tax_liens', 'Can unpaid taxes affect property ownership?', NULL, 'Yes, unpaid property taxes may create liens or legal issues that can affect ownership transfer and property rights.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(349, 'Legal', 'real_estate_fraud', 'What are common real estate scams?', NULL, 'Common scams may involve fake listings, fraudulent documents, identity theft, wire fraud, or misleading property information. Always verify information with trusted professionals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(350, 'Legal', 'document_storage', 'How long should I keep real estate documents?', NULL, 'Important property documents such as deeds, contracts, mortgage records, insurance documents, and improvement receipts should be kept securely for future reference.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:01', '2026-08-03 07:40:01'),
(351, 'Mortgage Planning', 'should_refinance', 'Should I refinance my mortgage?', NULL, 'Refinancing may be beneficial if you can reduce your interest rate, lower monthly payments, change your loan term, consolidate debt, or access home equity. Consider closing costs and your long-term goals before deciding.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(352, 'Mortgage Planning', 'what_is_heloc', 'What is a HELOC?', NULL, 'A HELOC (Home Equity Line of Credit) is a loan that allows homeowners to borrow against available equity in their property, usually with a revolving credit structure.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(353, 'Mortgage Planning', 'home_equity_loan', 'What is a home equity loan?', NULL, 'A home equity loan allows homeowners to borrow money using their property equity as collateral. It typically provides a lump-sum amount with scheduled repayments.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(354, 'Mortgage Planning', 'refinance_cost', 'How much does refinancing a mortgage cost?', NULL, 'Refinancing costs may include lender fees, appraisal fees, title fees, and other transaction expenses. Costs vary depending on the loan and lender.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(355, 'Mortgage Planning', 'lower_mortgage_payment', 'How can I lower my mortgage payment?', NULL, 'Options may include refinancing, extending the loan term, improving loan terms, removing certain costs, or reviewing insurance and tax expenses where applicable.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(356, 'Mortgage Planning', 'pay_off_mortgage_early', 'Should I pay off my mortgage early?', NULL, 'Paying off a mortgage early can reduce interest costs, but homeowners should also consider savings, investments, emergency funds, and other financial goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(357, 'Mortgage Planning', 'extra_mortgage_payment', 'Can I make extra payments toward my mortgage?', NULL, 'Many mortgages allow additional principal payments, but rules vary by lender and loan agreement. Check whether any restrictions or penalties apply.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(358, 'Mortgage Planning', 'debt_to_income_ratio', 'What is debt-to-income ratio?', NULL, 'Debt-to-income ratio compares your monthly debt payments to your gross monthly income. Lenders use it as one factor when evaluating mortgage applications.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(359, 'Mortgage Planning', 'improve_dti', 'How can I improve my debt-to-income ratio?', NULL, 'You can improve your debt-to-income ratio by reducing debt, increasing income, avoiding new debt, and managing monthly expenses effectively.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(360, 'Mortgage Planning', 'mortgage_rate_lock', 'What is a mortgage rate lock?', NULL, 'A mortgage rate lock allows a borrower to secure an interest rate for a specific period while completing the loan process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(361, 'Mortgage Planning', 'when_lock_rate', 'When should I lock my mortgage rate?', NULL, 'The decision to lock a rate depends on market conditions, lender options, closing timeline, and your personal risk preference.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(362, 'Mortgage Planning', 'interest_rate_change', 'How do interest rate changes affect home buying?', NULL, 'Higher rates generally increase borrowing costs and monthly payments, while lower rates may improve affordability and purchasing power.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(363, 'Mortgage Planning', 'mortgage_points', 'What are mortgage points?', NULL, 'Mortgage points are fees paid upfront to potentially reduce the interest rate on a mortgage. The benefit depends on how long you keep the loan.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(364, 'Mortgage Planning', 'buy_points', 'Should I buy mortgage points?', NULL, 'Buying points may make sense if you plan to keep the mortgage long enough to recover the upfront cost through lower payments.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(365, 'Mortgage Planning', 'mortgage_term_choice', 'Should I choose a 15-year or 30-year mortgage?', NULL, 'A shorter mortgage term usually has higher payments but may reduce total interest costs, while a longer term may provide lower monthly payments.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(366, 'Mortgage Planning', 'adjustable_rate_mortgage', 'What is an adjustable-rate mortgage?', NULL, 'An adjustable-rate mortgage has an interest rate that may change over time based on market conditions after an initial fixed period.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(367, 'Mortgage Planning', 'fixed_rate_mortgage', 'What is a fixed-rate mortgage?', NULL, 'A fixed-rate mortgage keeps the same interest rate for the agreed loan period, providing predictable monthly payments.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(368, 'Mortgage Planning', 'mortgage_after_bankruptcy', 'Can I get a mortgage after bankruptcy?', NULL, 'Mortgage eligibility after bankruptcy depends on the type of bankruptcy, time passed, credit recovery, lender requirements, and financial circumstances.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(369, 'Mortgage Planning', 'mortgage_after_foreclosure', 'Can I buy a home after foreclosure?', NULL, 'Buying after foreclosure may be possible after meeting waiting periods, rebuilding credit, and satisfying lender requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(370, 'Mortgage Planning', 'mortgage_for_investors', 'Can investors get mortgages for rental properties?', NULL, 'Yes, investors can obtain financing for rental properties, but requirements may differ from owner-occupied home loans.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(371, 'Mortgage Planning', 'multiple_mortgages', 'Can I have multiple mortgages?', NULL, 'Some borrowers can have multiple mortgages depending on income, credit history, debt levels, lender requirements, and financial goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(372, 'Mortgage Planning', 'cash_out_refinance', 'What is cash-out refinancing?', NULL, 'Cash-out refinancing replaces an existing mortgage with a larger loan and allows homeowners to access some of their home equity as cash.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(373, 'Mortgage Planning', 'mortgage_affordability_change', 'Can my mortgage affordability change over time?', NULL, 'Yes, affordability can change due to income changes, interest rates, debts, credit score changes, and personal financial circumstances.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(374, 'Mortgage Planning', 'financial_ready_homebuying', 'How do I know if I am financially ready to buy a home?', NULL, 'Financial readiness includes stable income, manageable debt, savings for down payment and closing costs, good credit habits, and a realistic monthly budget.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(375, 'Mortgage Planning', 'home_buying_budget_plan', 'How should I plan my budget before buying a home?', NULL, 'Create a budget that includes mortgage payments, taxes, insurance, utilities, maintenance, emergency savings, and other lifestyle expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:24', '2026-08-03 07:40:24'),
(376, 'Luxury Real Estate', 'what_is_luxury_real_estate', 'What is considered a luxury property?', NULL, 'A luxury property is generally a high-value home that offers premium features, exceptional location, superior design, privacy, unique amenities, or exclusive lifestyle benefits.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(377, 'Luxury Real Estate', 'buy_luxury_home', 'How do I buy a luxury home?', NULL, 'Buying a luxury home involves understanding your goals, identifying suitable properties, evaluating unique features, reviewing financial considerations, negotiating terms, and completing due diligence.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(378, 'Luxury Real Estate', 'luxury_home_agent', 'Do I need a specialized agent for luxury real estate?', NULL, 'A luxury real estate agent can provide specialized market knowledge, access to exclusive properties, privacy management, negotiation expertise, and tailored marketing strategies.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(379, 'Luxury Real Estate', 'luxury_property_value', 'How are luxury homes valued?', NULL, 'Luxury property valuation considers location, architectural design, unique features, land size, amenities, comparable sales, market demand, and buyer preferences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(380, 'Luxury Real Estate', 'private_listing', 'What is a private or off-market listing?', NULL, 'An off-market listing is a property that is not publicly advertised through traditional listing channels and may be shared privately with qualified buyers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(381, 'Luxury Real Estate', 'find_off_market_property', 'How can I find off-market luxury properties?', NULL, 'Luxury agents often use professional networks, private contacts, and market relationships to identify opportunities that may not be publicly available.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(382, 'Luxury Real Estate', 'luxury_home_features', 'What features are common in luxury homes?', NULL, 'Luxury homes may include custom architecture, smart home technology, premium finishes, pools, theaters, outdoor living spaces, security systems, and high-end amenities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(383, 'Luxury Real Estate', 'luxury_home_inspection', 'Do luxury homes need inspections?', NULL, 'Yes, inspections are important for luxury properties because they may include complex systems, specialized features, and significant maintenance requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(384, 'Luxury Real Estate', 'luxury_home_financing', 'How do people finance luxury homes?', NULL, 'Luxury buyers may use traditional financing, specialized lending programs, private banking services, or cash purchases depending on their financial situation.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(385, 'Luxury Real Estate', 'cash_luxury_purchase', 'Are luxury homes often purchased with cash?', NULL, 'Some luxury properties are purchased with cash, while others are financed. The best option depends on the buyer’s financial strategy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(386, 'Luxury Real Estate', 'luxury_home_marketing', 'How are luxury homes marketed?', NULL, 'Luxury marketing may include professional photography, video tours, targeted advertising, private showings, premium networks, and specialized branding.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(387, 'Luxury Real Estate', 'sell_luxury_home', 'How do I sell a luxury property?', NULL, 'Selling a luxury property involves strategic pricing, premium marketing, identifying qualified buyers, maintaining privacy, negotiating effectively, and managing a detailed transaction process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(388, 'Luxury Real Estate', 'luxury_home_staging', 'Is staging important for luxury homes?', NULL, 'Luxury staging can highlight architecture, lifestyle features, and design elements while helping buyers visualize the property’s potential.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(389, 'Luxury Real Estate', 'international_luxury_buyer', 'Can international buyers purchase luxury properties?', NULL, 'Yes, international buyers can purchase luxury properties, but they should understand local regulations, taxes, financing options, and ownership requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(390, 'Luxury Real Estate', 'foreign_buyer_process', 'What should foreign buyers know before buying property?', NULL, 'Foreign buyers should review financing, taxes, legal requirements, ownership structures, currency considerations, and local market conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(391, 'Luxury Real Estate', 'luxury_property_investment', 'Are luxury homes good investments?', NULL, 'Luxury properties may offer long-term value potential, but returns depend on location, demand, market conditions, maintenance costs, and investment goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(392, 'Luxury Real Estate', 'luxury_market_trends', 'How do luxury real estate markets work?', NULL, 'Luxury markets can behave differently from general housing markets due to limited inventory, unique properties, buyer profiles, and economic conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(393, 'Luxury Real Estate', 'luxury_home_privacy', 'How do luxury buyers maintain privacy?', NULL, 'Privacy may be supported through private showings, confidentiality agreements, controlled marketing, security measures, and professional representation.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(394, 'Luxury Real Estate', 'luxury_property_taxes', 'Are taxes higher on luxury properties?', NULL, 'Higher-value properties may have higher property taxes, but actual amounts depend on local tax rules, assessments, and property characteristics.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(395, 'Luxury Real Estate', 'luxury_home_renovation', 'Should I renovate a luxury home before selling?', NULL, 'Renovation decisions should consider market expectations, buyer preferences, costs, and whether improvements are likely to increase appeal and value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(396, 'Luxury Real Estate', 'luxury_home_showing', 'How are luxury home showings different?', NULL, 'Luxury showings often focus on privacy, personalized experiences, detailed presentations, and accommodating qualified buyers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(397, 'Luxury Real Estate', 'luxury_real_estate_network', 'Why are networks important in luxury real estate?', NULL, 'Strong networks help agents connect buyers and sellers, discover opportunities, and provide specialized services for high-value transactions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(398, 'Luxury Real Estate', 'luxury_second_home', 'Should I buy a luxury second home?', NULL, 'A luxury second home decision depends on lifestyle goals, financial planning, location, usage, maintenance, and investment considerations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(399, 'Luxury Real Estate', 'luxury_home_management', 'How are luxury properties maintained?', NULL, 'Luxury property maintenance often requires specialized services for landscaping, security, technology systems, pools, custom features, and ongoing care.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(400, 'Luxury Real Estate', 'luxury_agent_selection', 'How do I choose a luxury real estate agent?', NULL, 'Choose an agent with luxury market experience, strong reputation, discretion, negotiation skills, marketing expertise, and knowledge of the target area.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:40:47', '2026-08-03 07:40:47'),
(401, 'Life Changes', 'first_time_seller', 'What should first-time sellers know?', NULL, 'First-time sellers should understand the selling process, pricing strategy, preparation steps, marketing, negotiations, paperwork, and closing requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(402, 'Life Changes', 'selling_after_many_years', 'I have lived in my home for many years. How do I prepare to sell?', NULL, 'Start by organizing belongings, making necessary repairs, understanding your home value, preparing emotionally for the move, and creating a selling plan.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(403, 'Life Changes', 'downsizing_home', 'What is downsizing in real estate?', NULL, 'Downsizing means moving from a larger home to a smaller property that better fits your current lifestyle, needs, or financial goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(404, 'Life Changes', 'when_to_downsize', 'How do I know when it is time to downsize?', NULL, 'Many homeowners consider downsizing when maintenance becomes difficult, lifestyle needs change, family circumstances change, or they want to reduce expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(405, 'Life Changes', 'retirement_move', 'Should I sell my home when I retire?', NULL, 'Retirement decisions depend on finances, lifestyle goals, location preferences, healthcare needs, and long-term plans.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(406, 'Life Changes', 'empty_nest_selling', 'Should I sell my home after children move out?', NULL, 'Some homeowners choose to downsize after children leave, while others prefer to keep their home. The decision depends on personal goals and financial considerations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(407, 'Life Changes', 'inherited_property', 'What should I do with an inherited property?', NULL, 'Options may include selling, renting, keeping, or transferring the property. Consider legal requirements, taxes, maintenance, and personal circumstances.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(408, 'Life Changes', 'selling_inherited_home', 'How do I sell an inherited house?', NULL, 'Selling an inherited property may require reviewing ownership documents, completing required legal steps, preparing the property, determining value, and following the normal selling process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(409, 'Life Changes', 'estate_sale_property', 'What is an estate sale in real estate?', NULL, 'An estate sale may involve selling property owned by someone who has passed away or managing assets through an estate process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(410, 'Life Changes', 'divorce_home_sale', 'What happens to a home during divorce?', NULL, 'Property decisions during divorce depend on ownership, agreements, legal requirements, finances, and the decisions made by the parties involved.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(411, 'Life Changes', 'sell_home_after_divorce', 'Should we sell our home after divorce?', NULL, 'Selling a home after divorce may be an option depending on financial needs, ownership arrangements, legal agreements, and future plans.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(412, 'Life Changes', 'relocating_sell_home', 'Should I sell my home before relocating?', NULL, 'The decision depends on your timeline, finances, market conditions, and whether you prefer to sell before or after moving.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(413, 'Life Changes', 'moving_to_smaller_home', 'How do I prepare for moving into a smaller home?', NULL, 'Start by sorting belongings, prioritizing important items, measuring your new space, organizing storage, and planning the transition early.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(414, 'Life Changes', 'prepare_old_home_sale', 'How do I prepare an older home for sale?', NULL, 'Focus on safety, maintenance, repairs, cleanliness, presentation, and addressing issues that may affect buyer confidence.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(415, 'Life Changes', 'sell_as_is', 'Can I sell my home as-is?', NULL, 'Yes, homes can often be sold as-is, but pricing, disclosures, buyer expectations, and market conditions should be considered.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(416, 'Life Changes', 'selling_house_with_repairs', 'Should I repair my home before selling?', NULL, 'Repair decisions depend on cost, market expectations, property condition, and whether improvements are likely to increase buyer interest or value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(417, 'Life Changes', 'emotional_home_sale', 'How do I handle the emotional process of selling my home?', NULL, 'Selling a long-time home can be emotional. Planning ahead, focusing on future goals, and working with supportive professionals can make the transition easier.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(418, 'Life Changes', 'selling_family_home', 'What should families consider when selling a family home?', NULL, 'Families should discuss timing, property value, emotional considerations, financial goals, and responsibilities among family members.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(419, 'Life Changes', 'senior_home_sale', 'What options do seniors have when selling a home?', NULL, 'Seniors may consider downsizing, relocating, moving closer to family, retirement communities, renting, or other housing options based on their needs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(420, 'Life Changes', 'moving_assistance', 'Can a real estate agent help with moving plans?', NULL, 'Many agents can provide guidance and connect clients with local resources such as movers, contractors, storage providers, and other services.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(421, 'Life Changes', 'home_cleanout', 'How do I clean out a home before selling?', NULL, 'Home cleanout may involve sorting belongings, donating items, organizing valuables, removing unwanted items, and preparing the property for buyers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(422, 'Life Changes', 'selling_home_quickly', 'How can I sell my home quickly?', NULL, 'A faster sale may involve proper pricing, effective marketing, property preparation, flexible scheduling, and responding quickly to buyer interest.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(423, 'Life Changes', 'sell_home_privately', 'Can I sell my home privately without an agent?', NULL, 'Some owners choose to sell privately, but professional guidance can help with pricing, marketing, negotiations, paperwork, and transaction management.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(424, 'Life Changes', 'life_event_real_estate', 'Can a real estate agent help during major life changes?', NULL, 'Yes, real estate professionals often help clients navigate housing decisions during relocation, retirement, family changes, inheritance, and other transitions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(425, 'Life Changes', 'future_home_needs', 'How do I choose a home that fits my future needs?', NULL, 'Consider lifestyle changes, family plans, accessibility, maintenance requirements, finances, location, and long-term goals when choosing a property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:16', '2026-08-03 07:41:16'),
(426, 'Home Search', 'find_home_listings', 'Where can I find homes for sale?', NULL, 'Homes for sale can be found through online listing platforms, real estate agents, brokerage websites, and local property marketing channels.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(427, 'Home Search', 'property_search_help', 'Can you help me search for available properties?', NULL, 'Yes, I can help you define your property needs, search criteria, budget, preferred locations, and connect you with suitable listings.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(428, 'Home Search', 'filter_home_search', 'How do I narrow down my home search?', NULL, 'Start by identifying your budget, preferred location, property type, size, number of bedrooms, lifestyle needs, and must-have features.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(429, 'Home Search', 'bedroom_requirement', 'How many bedrooms should I buy?', NULL, 'The right number of bedrooms depends on your current needs, future plans, family size, lifestyle, and budget.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(430, 'Home Search', 'bathroom_requirement', 'How many bathrooms do I need?', NULL, 'Bathroom needs depend on household size, lifestyle, resale value considerations, and personal preferences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(431, 'Home Search', 'square_footage', 'How much square footage do I need?', NULL, 'The ideal size depends on your lifestyle, number of occupants, budget, maintenance preferences, and future needs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(432, 'Home Search', 'property_type', 'What type of property should I buy?', NULL, 'Property choices include houses, condos, townhomes, apartments, and other options. The best choice depends on your lifestyle, budget, and ownership goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(433, 'Home Search', 'townhouse_vs_condo', 'What is the difference between a townhouse and a condo?', NULL, 'A townhouse usually provides more private space and may include land ownership, while a condo often involves shared ownership of common areas and amenities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(434, 'Home Search', 'single_family_home', 'What is a single-family home?', NULL, 'A single-family home is a residential property designed for one household and typically includes private living space and ownership of the surrounding property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(435, 'Home Search', 'new_construction_home', 'Should I buy a new construction home?', NULL, 'New construction homes may offer modern features, warranties, and customization options, but buyers should evaluate location, builder reputation, costs, and future value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(436, 'Home Search', 'builder_reputation', 'How do I evaluate a home builder?', NULL, 'Research builder experience, reviews, completed projects, warranties, construction quality, communication, and customer service history.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(437, 'Home Search', 'smart_home_features', 'What are smart home features?', NULL, 'Smart home features may include automated lighting, security systems, thermostats, appliances, cameras, and technology that improves convenience and efficiency.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(438, 'Home Search', 'energy_efficient_home', 'What makes a home energy efficient?', NULL, 'Energy-efficient homes may include insulation improvements, efficient appliances, upgraded windows, smart systems, and energy-saving designs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(439, 'Home Search', 'garage_importance', 'How important is having a garage?', NULL, 'Garage importance depends on location, climate, vehicle needs, storage requirements, and personal preferences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(440, 'Home Search', 'yard_space', 'How important is outdoor space?', NULL, 'Outdoor space can improve lifestyle, recreation options, privacy, and property appeal depending on buyer preferences and location.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(441, 'Home Search', 'hoa_property', 'Should I buy a home with an HOA?', NULL, 'An HOA may provide community services and amenities but also includes fees and rules. Review HOA documents before purchasing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(442, 'Home Search', 'open_house_visit', 'What should I look for during an open house?', NULL, 'Look at property condition, layout, natural light, storage, neighborhood, possible repairs, and whether the home fits your needs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(443, 'Home Search', 'compare_properties', 'How do I compare different homes?', NULL, 'Compare location, price, condition, size, features, future value, monthly costs, and how well each property meets your priorities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(444, 'Home Search', 'property_photos', 'Can I trust online property photos?', NULL, 'Photos are helpful but may not show every detail. Buyers should visit properties, review disclosures, and conduct inspections before purchasing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(445, 'Home Search', 'virtual_home_tour', 'What is a virtual home tour?', NULL, 'A virtual home tour allows buyers to explore a property online through videos, interactive views, or digital walkthroughs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(446, 'Home Search', 'home_listing_status', 'What do listing statuses mean?', NULL, 'Listing statuses indicate whether a property is available, under contract, pending, sold, or temporarily unavailable depending on the listing system.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(447, 'Home Search', 'pending_home', 'Can I buy a home that is pending?', NULL, 'A pending property may still have limited opportunities depending on the transaction status, seller decisions, and local practices.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(448, 'Home Search', 'expired_listing', 'What is an expired listing?', NULL, 'An expired listing is a property that was listed for sale but did not sell during the listing agreement period.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(449, 'Home Search', 'price_reduced_listing', 'What does price reduced mean on a listing?', NULL, 'A price reduction means the seller has lowered the asking price, often to attract more buyer interest.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(450, 'Home Search', 'property_amenities', 'What amenities should I look for in a home?', NULL, 'Important amenities depend on your lifestyle and may include parking, storage, outdoor areas, technology, community features, transportation access, and nearby services.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:41:41', '2026-08-03 07:41:41'),
(451, 'Real Estate Technology', 'online_home_search', 'Can I search for homes online?', NULL, 'Yes, buyers can search properties online using real estate websites, listing platforms, brokerage websites, and digital property tools.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(452, 'Real Estate Technology', 'ai_real_estate_help', 'How can AI help with real estate?', NULL, 'AI can help answer questions, analyze property information, organize searches, provide market insights, and assist buyers and sellers with general guidance.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(453, 'Real Estate Technology', 'chatbot_real_estate', 'What can a real estate chatbot help me with?', NULL, 'A real estate chatbot can answer common questions, provide property information, explain processes, collect client details, and help users connect with agents.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(454, 'Real Estate Technology', 'online_property_valuation', 'Can I get a property value estimate online?', NULL, 'Online valuation tools can provide estimates based on available data, but a professional valuation may require a detailed market analysis and property review.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(455, 'Real Estate Technology', 'virtual_property_tour', 'How do virtual property tours work?', NULL, 'Virtual tours allow buyers to explore homes remotely through videos, 3D walkthroughs, interactive views, and digital presentations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(456, 'Real Estate Technology', 'digital_signature', 'Can real estate documents be signed online?', NULL, 'Many real estate documents can be signed electronically where permitted by local laws and transaction requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(457, 'Real Estate Technology', 'remote_closing_technology', 'Can technology help with remote real estate closing?', NULL, 'Technology can support remote transactions through electronic documents, online communication, digital verification, and approved closing processes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(458, 'Real Estate Technology', 'online_mortgage_application', 'Can I apply for a mortgage online?', NULL, 'Many lenders offer online mortgage applications, document uploads, status tracking, and digital communication options.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(459, 'Real Estate Technology', 'property_alerts', 'How do property alerts work?', NULL, 'Property alerts notify buyers when new listings, price changes, or matching properties become available based on selected search criteria.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(460, 'Real Estate Technology', 'smart_home_technology', 'What is smart home technology?', NULL, 'Smart home technology uses connected devices to improve convenience, security, energy efficiency, and home management.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(461, 'Real Estate Technology', 'real_estate_apps', 'Are real estate apps useful?', NULL, 'Real estate apps can help users search listings, compare properties, track market activity, communicate with agents, and organize property information.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(462, 'Real Estate Technology', 'digital_market_analysis', 'What is a digital market analysis?', NULL, 'A digital market analysis uses online data and tools to evaluate property trends, comparable sales, pricing activity, and market conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14');
INSERT INTO `real_estate_faqs` (`id`, `category`, `intent_name`, `user_question`, `question_variations`, `answer`, `required_information`, `agent_handoff`, `keywords`, `language`, `status`, `created_at`, `updated_at`) VALUES
(463, 'Real Estate Technology', 'virtual_staging', 'What is virtual staging?', NULL, 'Virtual staging uses digital technology to add furniture, design elements, or improvements to property images to help buyers visualize spaces.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(464, 'Real Estate Technology', 'online_listing_photos', 'Why are professional listing photos important?', NULL, 'Professional photos can improve property presentation, attract more interest, and help buyers understand the home before scheduling a visit.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(465, 'Real Estate Technology', 'real_estate_video_marketing', 'Why are property videos important?', NULL, 'Property videos provide a more detailed experience by showing layouts, features, location highlights, and overall property flow.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(466, 'Real Estate Technology', 'drone_real_estate_photos', 'How are drones used in real estate?', NULL, 'Drones can capture aerial photos and videos that showcase property size, surroundings, land features, and location advantages.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(467, 'Real Estate Technology', 'online_agent_consultation', 'Can I meet with a real estate agent online?', NULL, 'Yes, many agents offer virtual consultations through video calls, messaging, and online scheduling tools.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(468, 'Real Estate Technology', 'digital_property_documents', 'Can I store real estate documents digitally?', NULL, 'Yes, many homeowners and professionals store property documents electronically while maintaining secure backups and proper organization.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(469, 'Real Estate Technology', 'property_data_accuracy', 'Is online property information always accurate?', NULL, 'Online information is useful but may change or contain outdated details. Verify important information with reliable sources and professionals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(470, 'Real Estate Technology', 'ai_home_recommendations', 'Can AI recommend homes for me?', NULL, 'AI tools can suggest properties based on preferences, budget, and search behavior, but buyers should still evaluate properties carefully.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(471, 'Real Estate Technology', 'automated_home_search', 'What is automated home searching?', NULL, 'Automated home searching uses technology to match buyers with properties based on selected criteria and preferences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(472, 'Real Estate Technology', 'online_real_estate_marketplace', 'What is an online real estate marketplace?', NULL, 'An online real estate marketplace is a digital platform where users can view listings, compare properties, and connect with buyers, sellers, or agents.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(473, 'Real Estate Technology', 'property_crm', 'What is a real estate CRM?', NULL, 'A real estate CRM is a system used by agents and companies to manage leads, clients, communications, follow-ups, and transaction information.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(474, 'Real Estate Technology', 'real_estate_data_security', 'How is my real estate information protected online?', NULL, 'Real estate platforms should use security practices to protect personal information, documents, and communications. Users should also follow safe online practices.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(475, 'Real Estate Technology', 'future_real_estate_ai', 'Will AI replace real estate agents?', NULL, 'AI can improve efficiency and provide information, but many buyers and sellers still need human expertise for negotiation, local knowledge, decision-making, and transaction guidance.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:14', '2026-08-03 07:42:14'),
(476, 'International Real Estate', 'buy_property_abroad', 'Can foreigners buy property in another country?', NULL, 'Many countries allow foreign buyers to purchase real estate, but rules, ownership restrictions, taxes, and approval requirements vary by location.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(477, 'International Real Estate', 'international_buyer_process', 'What is the process for international buyers?', NULL, 'International buyers typically research markets, work with local professionals, understand legal requirements, arrange financing, complete due diligence, and finalize ownership transfer.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(478, 'International Real Estate', 'foreign_investor', 'Can foreign investors buy real estate?', NULL, 'Foreign investors may purchase real estate in many markets, but they should review local regulations, taxes, financing options, and investment requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(479, 'International Real Estate', 'international_real_estate_agent', 'Do I need a local real estate agent when buying abroad?', NULL, 'A local real estate agent can provide valuable market knowledge, language support, property access, and guidance on local transaction practices.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(480, 'International Real Estate', 'foreign_buyer_tax', 'Do foreign buyers pay additional taxes?', NULL, 'Some locations apply additional taxes, fees, or restrictions for foreign buyers. Requirements vary depending on the country and region.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(481, 'International Real Estate', 'currency_exchange_property', 'How does currency exchange affect international property purchases?', NULL, 'Currency exchange rates can affect purchase costs, mortgage payments, and investment returns. Buyers should consider currency risks when planning.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(482, 'International Real Estate', 'international_property_financing', 'Can international buyers get a mortgage?', NULL, 'Some lenders provide financing to international buyers, but requirements may include income verification, documentation, deposits, and additional approvals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(483, 'International Real Estate', 'cash_purchase_abroad', 'Can I buy international property with cash?', NULL, 'Yes, some international buyers purchase properties with cash, but they should still complete legal reviews, due diligence, and proper documentation.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(484, 'International Real Estate', 'international_property_inspection', 'Should I inspect a property before buying internationally?', NULL, 'Yes, inspections are important to understand property condition, potential repairs, construction quality, and future maintenance needs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(485, 'International Real Estate', 'international_title_search', 'How do I verify ownership of a property abroad?', NULL, 'Buyers should work with qualified local professionals to review ownership records, title information, legal documents, and property history.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(486, 'International Real Estate', 'international_property_lawyer', 'Do I need a lawyer when buying property in another country?', NULL, 'A local real estate lawyer can help review contracts, explain legal requirements, verify documents, and protect buyer interests.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(487, 'International Real Estate', 'international_real_estate_risks', 'What are the risks of buying property internationally?', NULL, 'Risks may include currency changes, legal differences, unfamiliar markets, ownership restrictions, taxes, property management challenges, and market fluctuations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(488, 'International Real Estate', 'vacation_home_purchase', 'Should I buy a vacation home in another country?', NULL, 'A vacation home decision depends on personal use, financial goals, location, maintenance responsibilities, rental potential, and long-term plans.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(489, 'International Real Estate', 'international_rental_income', 'Can I rent out an international property?', NULL, 'Many international property owners rent their properties, but rental rules, taxes, permits, and management requirements vary by location.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(490, 'International Real Estate', 'manage_property_abroad', 'How do I manage a property in another country?', NULL, 'Owners can use local property managers, maintenance providers, technology tools, and trusted professionals to manage overseas properties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(491, 'International Real Estate', 'international_real_estate_return', 'How do I evaluate international property investment returns?', NULL, 'Evaluate purchase costs, rental income potential, expenses, taxes, market growth, currency effects, and local economic conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(492, 'International Real Estate', 'foreign_buyer_documents', 'What documents do international buyers need?', NULL, 'Documents may include identification, financial records, proof of funds, tax information, and legal paperwork required by local authorities or lenders.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(493, 'International Real Estate', 'international_closing_process', 'How does international property closing work?', NULL, 'Closing procedures vary by country and may involve legal representatives, government offices, financial institutions, title services, and document verification.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(494, 'International Real Estate', 'remote_property_purchase', 'Can I buy property internationally without traveling?', NULL, 'Some purchases can be completed remotely using virtual tours, local representatives, digital documents, and approved legal processes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(495, 'International Real Estate', 'international_market_research', 'How do I research a foreign real estate market?', NULL, 'Research should include property prices, economic conditions, regulations, rental demand, taxes, infrastructure, and local market trends.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(496, 'International Real Estate', 'foreign_property_ownership', 'How is foreign property ownership recorded?', NULL, 'Ownership records and registration systems vary by country. Local professionals can explain the process and requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(497, 'International Real Estate', 'international_investment_strategy', 'What are common international real estate investment strategies?', NULL, 'Strategies may include vacation rentals, long-term rentals, appreciation opportunities, diversification, and lifestyle purchases.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(498, 'International Real Estate', 'international_property_management_cost', 'How much does overseas property management cost?', NULL, 'Costs vary depending on location, services provided, property type, rental activity, and management agreement terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(499, 'International Real Estate', 'international_real_estate_market', 'How do I compare real estate markets in different countries?', NULL, 'Compare affordability, economic stability, ownership rules, taxes, rental demand, infrastructure, and long-term growth potential.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(500, 'International Real Estate', 'international_buyer_support', 'Can a real estate agent help international buyers?', NULL, 'Yes, experienced agents can help international buyers understand markets, find properties, coordinate professionals, and navigate the purchase process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:42:50', '2026-08-03 07:42:50'),
(501, 'Real Estate Investment', 'real_estate_investing', 'How do I start investing in real estate?', NULL, 'Start by understanding your investment goals, budget, financing options, market conditions, property types, risks, and expected returns.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:43:16', '2026-08-03 07:43:16'),
(502, 'Real Estate Investment', 'why_invest_real_estate', 'Why do people invest in real estate?', NULL, 'People invest in real estate for potential rental income, long-term appreciation, portfolio diversification, tax benefits, and wealth building opportunities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:43:16', '2026-08-03 07:43:16'),
(503, 'Real Estate Investment', 'investment_property', 'What is an investment property?', NULL, 'An investment property is real estate purchased primarily to generate income, appreciation, or financial returns rather than for personal residence.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:43:16', '2026-08-03 07:43:16'),
(504, 'Real Estate Investment', 'rental_income', 'How do rental properties make money?', NULL, 'Rental properties generate income through tenant payments, which may provide cash flow after expenses such as mortgage, taxes, insurance, maintenance, and management costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:43:16', '2026-08-03 07:43:16'),
(505, 'Real Estate Investment', 'cash_flow_property', 'What is positive cash flow in real estate?', NULL, 'Positive cash flow occurs when rental income exceeds operating expenses and financing costs associated with a property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:43:16', '2026-08-03 07:43:16'),
(506, 'Real Estate Investment', 'negative_cash_flow', 'What is negative cash flow in real estate?', NULL, 'Negative cash flow occurs when property expenses exceed rental income, requiring the owner to contribute additional funds.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:43:16', '2026-08-03 07:43:16'),
(507, 'Real Estate Investment', 'rental_yield', 'What is rental yield?', NULL, 'Rental yield measures the income generated by a rental property compared with the property value or investment amount.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:43:16', '2026-08-03 07:43:16'),
(508, 'Real Estate Investment', 'roi_real_estate', 'How do I calculate real estate ROI?', NULL, 'Real estate ROI measures investment performance by comparing gains, income, and costs associated with owning the property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:43:16', '2026-08-03 07:43:16'),
(509, 'Real Estate Investment', 'property_appreciation', 'What is property appreciation?', NULL, 'Property appreciation is the increase in a property’s value over time due to factors such as market demand, improvements, location, and economic conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:43:16', '2026-08-03 07:43:16'),
(510, 'Real Estate Investment', 'property_depreciation', 'What is property depreciation?', NULL, 'Property depreciation refers to the decline in value or accounting expense associated with property wear, age, and other factors depending on applicable rules.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:43:16', '2026-08-03 07:43:16'),
(511, 'Real Estate Investment', 'fix_and_flip', 'What is house flipping?', NULL, 'House flipping involves purchasing a property, improving it, and selling it for a potential profit within a shorter timeframe.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:43:16', '2026-08-03 07:43:16'),
