(596, 'Construction & Renovation', 'renovation_financing', 'How can I finance home renovations?', NULL, 'Renovation financing options may include savings, personal loans, home equity loans, HELOCs, or specialized renovation mortgage programs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:44:51', '2026-08-03 07:44:51'),
(597, 'Construction & Renovation', 'fixer_upper_home', 'Is buying a fixer-upper a good idea?', NULL, 'A fixer-upper can provide opportunities for customization and potential value growth, but buyers should carefully evaluate repair costs and risks.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:44:51', '2026-08-03 07:44:51'),
(598, 'Construction & Renovation', 'construction_defects', 'What should I do if I find construction defects?', NULL, 'Document the issue, review warranties or agreements, communicate with responsible parties, and seek professional advice when necessary.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:44:51', '2026-08-03 07:44:51'),
(599, 'Construction & Renovation', 'home_warranty_new_build', 'Do new homes come with warranties?', NULL, 'Many new homes include builder warranties covering certain issues for specific periods, depending on the builder and local requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:44:51', '2026-08-03 07:44:51'),
(600, 'Construction & Renovation', 'renovation_project_planning', 'How do I plan a successful renovation?', NULL, 'Successful renovations require clear goals, realistic budgets, qualified professionals, proper permits, good communication, and regular project monitoring.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:44:51', '2026-08-03 07:44:51'),
(601, 'Real Estate Careers', 'become_real_estate_agent', 'How do I become a real estate agent?', NULL, 'To become a real estate agent, you typically need to complete required education, pass a licensing exam, meet local requirements, and work under a licensed brokerage where required.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(602, 'Real Estate Careers', 'real_estate_license', 'What is required to get a real estate license?', NULL, 'Requirements vary by location but commonly include education courses, examinations, application procedures, background checks, and continuing education.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(603, 'Real Estate Careers', 'real_estate_broker', 'What is the difference between an agent and a broker?', NULL, 'A real estate agent helps clients buy and sell properties, while a broker usually has additional qualifications and may manage a brokerage or supervise agents.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(604, 'Real Estate Careers', 'real_estate_brokerage', 'What is a real estate brokerage?', NULL, 'A brokerage is a company or organization where licensed real estate professionals operate and provide real estate services.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(605, 'Real Estate Careers', 'work_as_real_estate_agent', 'What is it like working as a real estate agent?', NULL, 'Real estate agents work with clients, market properties, negotiate transactions, build relationships, manage schedules, and handle ongoing business activities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(606, 'Real Estate Careers', 'real_estate_agent_income', 'How much money do real estate agents make?', NULL, 'Agent income varies based on location, experience, market conditions, transaction volume, commission structure, expenses, and business skills.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(607, 'Real Estate Careers', 'real_estate_agent_commission', 'How do real estate commissions work?', NULL, 'Commission structures vary by transaction and agreement. Compensation depends on the services provided and terms established between parties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(608, 'Real Estate Careers', 'real_estate_agent_training', 'What training do real estate agents need?', NULL, 'Training typically includes licensing education, market knowledge, sales skills, negotiation, contracts, ethics, technology, and ongoing professional development.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(609, 'Real Estate Careers', 'real_estate_success', 'How do successful real estate agents build their business?', NULL, 'Successful agents focus on client relationships, market knowledge, communication, marketing, networking, follow-up, and providing excellent service.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(610, 'Real Estate Careers', 'real_estate_agent_marketing', 'Why is marketing important for real estate agents?', NULL, 'Marketing helps agents attract clients, promote properties, build reputation, generate leads, and maintain visibility in competitive markets.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(611, 'Real Estate Careers', 'real_estate_leads', 'How do real estate agents find clients?', NULL, 'Agents generate leads through referrals, networking, online marketing, advertising, community involvement, past clients, and professional connections.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(612, 'Real Estate Careers', 'real_estate_agent_specialization', 'Can real estate agents specialize in certain areas?', NULL, 'Yes, agents may specialize in residential, commercial, luxury, investment, relocation, rentals, new construction, or specific geographic markets.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(613, 'Real Estate Careers', 'real_estate_team', 'What is a real estate team?', NULL, 'A real estate team is a group of professionals who collaborate on sales, marketing, client service, administration, and transaction support.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18');
INSERT INTO `real_estate_faqs` (`id`, `category`, `intent_name`, `user_question`, `question_variations`, `answer`, `required_information`, `agent_handoff`, `keywords`, `language`, `status`, `created_at`, `updated_at`) VALUES
(614, 'Real Estate Careers', 'real_estate_assistant', 'What does a real estate assistant do?', NULL, 'A real estate assistant helps with administrative tasks, scheduling, marketing, client communication, documents, and transaction coordination.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(615, 'Real Estate Careers', 'transaction_coordinator', 'What is a transaction coordinator?', NULL, 'A transaction coordinator manages paperwork, deadlines, communication, and administrative details during a real estate transaction.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(616, 'Real Estate Careers', 'real_estate_appraiser', 'What does a real estate appraiser do?', NULL, 'A real estate appraiser evaluates properties and provides professional opinions of value based on market data, property condition, and comparable sales.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(617, 'Real Estate Careers', 'home_inspector_role', 'What does a home inspector do?', NULL, 'A home inspector evaluates a property’s condition, identifies potential issues, and provides information to help buyers make informed decisions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(618, 'Real Estate Careers', 'property_manager_career', 'What does a property manager do?', NULL, 'A property manager handles rental property operations including tenants, maintenance, rent collection, inspections, and administrative responsibilities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(619, 'Real Estate Careers', 'real_estate_investor_role', 'What does a real estate investor do?', NULL, 'A real estate investor purchases, manages, develops, or sells properties to generate income, appreciation, or investment returns.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(620, 'Real Estate Careers', 'real_estate_industry_jobs', 'What careers are available in real estate?', NULL, 'Real estate careers include agents, brokers, appraisers, inspectors, property managers, developers, lenders, analysts, and transaction professionals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(621, 'Real Estate Careers', 'real_estate_side_business', 'Can real estate be a part-time career?', NULL, 'Some people work in real estate part-time, but success requires commitment, training, client service, and effective time management.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(622, 'Real Estate Careers', 'real_estate_continuing_education', 'Why do real estate professionals need continuing education?', NULL, 'Continuing education helps professionals stay updated on laws, market trends, technology, ethics, and industry practices.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(623, 'Real Estate Careers', 'real_estate_ethics', 'Why are ethics important in real estate?', NULL, 'Ethical practices help protect clients, maintain trust, support fair transactions, and ensure compliance with professional standards.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(624, 'Real Estate Careers', 'real_estate_future', 'What is the future of the real estate industry?', NULL, 'The real estate industry continues to evolve through technology, changing consumer behavior, market trends, digital tools, and new service models.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(625, 'Real Estate Careers', 'real_estate_agent_ai', 'How will AI affect real estate agents?', NULL, 'AI can help agents improve efficiency, automate tasks, analyze information, and enhance client service while human expertise remains important for relationships and negotiations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:18', '2026-08-03 07:45:18'),
(626, 'Property Costs', 'property_tax', 'What are property taxes?', NULL, 'Property taxes are payments made by property owners to local governments based on the assessed value of their property. They help fund public services and infrastructure.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(627, 'Property Costs', 'property_tax_calculation', 'How are property taxes calculated?', NULL, 'Property taxes are generally calculated using the assessed property value and the local tax rate, which varies by location.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(628, 'Property Costs', 'property_tax_increase', 'Why do property taxes increase?', NULL, 'Property taxes may increase due to rising property values, changes in tax rates, improvements to the property, or local government decisions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(629, 'Property Costs', 'property_tax_exemption', 'Are there property tax exemptions available?', NULL, 'Some homeowners may qualify for tax exemptions or reductions depending on location, property type, age, disability status, veteran status, or other qualifying factors.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(630, 'Property Costs', 'property_tax_appeal', 'Can I appeal my property tax assessment?', NULL, 'Property owners may be able to appeal an assessment if they believe the property value has been incorrectly determined, following local procedures.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(631, 'Property Costs', 'homeowners_insurance', 'What is homeowners insurance?', NULL, 'Homeowners insurance helps protect a property and belongings against certain risks such as damage, theft, liability, and other covered events.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(632, 'Property Costs', 'homeowners_insurance_cost', 'How much does homeowners insurance cost?', NULL, 'Insurance costs vary based on location, property value, coverage level, risk factors, deductible choices, and insurance provider.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(633, 'Property Costs', 'insurance_coverage', 'What does homeowners insurance cover?', NULL, 'Coverage varies but may include damage to the home, personal belongings, liability protection, and certain additional expenses depending on the policy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(634, 'Property Costs', 'flood_insurance', 'Do I need flood insurance?', NULL, 'Flood insurance requirements depend on location, flood risk, lender requirements, and personal protection preferences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(635, 'Property Costs', 'earthquake_insurance', 'Do I need earthquake insurance?', NULL, 'Earthquake insurance may be considered in areas with earthquake risk. Coverage needs depend on location, property type, and personal circumstances.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(636, 'Property Costs', 'landlord_insurance', 'What insurance do rental property owners need?', NULL, 'Rental property owners often use landlord insurance, which may provide coverage for the property, liability, and rental-related risks.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(637, 'Property Costs', 'hoa_fees_cost', 'What are HOA fees used for?', NULL, 'HOA fees may cover shared amenities, landscaping, maintenance, community services, repairs, and other common expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(638, 'Property Costs', 'monthly_home_costs', 'What monthly costs come with owning a home?', NULL, 'Monthly ownership costs may include mortgage payments, taxes, insurance, utilities, maintenance, HOA fees, and other property expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(639, 'Property Costs', 'home_maintenance_cost', 'How much should I budget for home maintenance?', NULL, 'Maintenance costs vary by property age, size, condition, location, and systems. Homeowners should plan for regular upkeep and unexpected repairs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(640, 'Property Costs', 'hidden_home_costs', 'What are hidden costs of buying a home?', NULL, 'Hidden costs may include closing costs, repairs, maintenance, insurance changes, taxes, utilities, moving expenses, and upgrades.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(641, 'Property Costs', 'utility_costs_home', 'How much do utilities cost for a home?', NULL, 'Utility costs depend on home size, location, energy efficiency, climate, usage habits, and local utility rates.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(642, 'Property Costs', 'closing_costs', 'What are closing costs?', NULL, 'Closing costs are expenses paid during the final stage of a real estate transaction and may include lender fees, title services, taxes, insurance, and other charges.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(643, 'Property Costs', 'buyer_closing_costs', 'Who pays closing costs when buying a home?', NULL, 'Closing cost responsibilities vary by transaction, location, contract terms, lender requirements, and negotiations between parties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(644, 'Property Costs', 'seller_closing_costs', 'What costs do sellers pay when selling a home?', NULL, 'Sellers may pay expenses such as agent compensation, taxes, title-related costs, repairs, concessions, and other transaction fees depending on the agreement.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(645, 'Property Costs', 'homeownership_budget', 'How do I budget for owning a home?', NULL, 'Create a budget that includes mortgage payments, taxes, insurance, maintenance, utilities, repairs, savings, and lifestyle expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(646, 'Property Costs', 'emergency_home_fund', 'Should homeowners have an emergency fund?', NULL, 'Yes, an emergency fund can help cover unexpected repairs, maintenance issues, income changes, and other home-related expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(647, 'Property Costs', 'home_warranty', 'What is a home warranty?', NULL, 'A home warranty is a service agreement that may help cover repair or replacement costs for certain home systems and appliances, depending on the plan.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(648, 'Property Costs', 'home_warranty_vs_insurance', 'What is the difference between home warranty and homeowners insurance?', NULL, 'Homeowners insurance generally covers certain damages and risks, while a home warranty typically covers repair or replacement of selected systems and appliances.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(649, 'Property Costs', 'ownership_affordability', 'How do I know if I can afford homeownership?', NULL, 'Consider income, debts, savings, mortgage costs, taxes, insurance, maintenance, and long-term financial goals before buying.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(650, 'Property Costs', 'total_cost_homeownership', 'What is the true cost of owning a home?', NULL, 'The true cost includes purchase expenses, financing, taxes, insurance, maintenance, repairs, utilities, improvements, and ongoing ownership responsibilities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:45:51', '2026-08-03 07:45:51'),
(651, 'Commercial Real Estate', 'what_is_commercial_real_estate', 'What is commercial real estate?', NULL, 'Commercial real estate includes properties used for business purposes, such as offices, retail spaces, industrial buildings, warehouses, and other income-producing properties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(652, 'Commercial Real Estate', 'commercial_vs_residential', 'What is the difference between commercial and residential real estate?', NULL, 'Residential real estate is primarily used for housing, while commercial real estate is used for business operations, investment, and income generation.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(653, 'Commercial Real Estate', 'types_of_commercial_property', 'What types of commercial properties exist?', NULL, 'Commercial properties include office buildings, retail spaces, restaurants, warehouses, industrial facilities, hotels, medical buildings, and mixed-use developments.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(654, 'Commercial Real Estate', 'buy_commercial_property', 'How do I buy a commercial property?', NULL, 'Buying commercial property involves identifying goals, analyzing finances, evaluating locations, reviewing property performance, completing due diligence, and negotiating the purchase.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(655, 'Commercial Real Estate', 'commercial_property_investment', 'Is commercial real estate a good investment?', NULL, 'Commercial real estate can provide income and appreciation potential, but investors should evaluate risks, market conditions, financing, expenses, and property performance.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(656, 'Commercial Real Estate', 'commercial_property_value', 'How are commercial properties valued?', NULL, 'Commercial properties are often valued based on income potential, comparable sales, replacement cost, location, tenant quality, and market conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(657, 'Commercial Real Estate', 'cap_rate', 'What is capitalization rate (cap rate)?', NULL, 'Cap rate is a metric used by investors to estimate the potential return of a commercial property based on operating income and property value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(658, 'Commercial Real Estate', 'net_operating_income', 'What is net operating income (NOI)?', NULL, 'Net operating income is the income generated by a property after operating expenses but before financing costs and certain other deductions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(659, 'Commercial Real Estate', 'commercial_lease', 'What is a commercial lease?', NULL, 'A commercial lease is an agreement between a property owner and a business tenant outlining rental terms, responsibilities, costs, and conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(660, 'Commercial Real Estate', 'types_commercial_leases', 'What are different types of commercial leases?', NULL, 'Common commercial leases include gross leases, net leases, modified leases, and other structures where expenses are shared differently between landlord and tenant.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(661, 'Commercial Real Estate', 'triple_net_lease', 'What is a triple net lease?', NULL, 'A triple net lease typically requires tenants to pay rent plus certain property expenses such as taxes, insurance, and maintenance costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(662, 'Commercial Real Estate', 'commercial_rent', 'How is commercial rent determined?', NULL, 'Commercial rent depends on location, property type, size, market demand, tenant improvements, lease terms, and operating costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(663, 'Commercial Real Estate', 'business_location', 'Why is location important for commercial property?', NULL, 'Location affects customer access, visibility, employee convenience, business performance, tenant demand, and long-term property value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(664, 'Commercial Real Estate', 'commercial_property_financing', 'How is commercial real estate financed?', NULL, 'Commercial financing may involve banks, private lenders, investors, commercial mortgages, or other financing structures based on the property and borrower qualifications.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(665, 'Commercial Real Estate', 'commercial_mortgage', 'What is a commercial mortgage?', NULL, 'A commercial mortgage is a loan used to purchase or refinance property intended for business or investment purposes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(666, 'Commercial Real Estate', 'commercial_due_diligence', 'What is commercial real estate due diligence?', NULL, 'Due diligence involves reviewing financial records, leases, inspections, zoning, environmental issues, property condition, and legal documents before purchase.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(667, 'Commercial Real Estate', 'tenant_improvements', 'What are tenant improvements?', NULL, 'Tenant improvements are modifications made to a commercial space to meet a business tenant’s operational and design requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(668, 'Commercial Real Estate', 'commercial_property_management', 'What does commercial property management include?', NULL, 'Commercial property management may include tenant relations, maintenance, leasing, rent collection, repairs, inspections, and financial reporting.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(669, 'Commercial Real Estate', 'office_space_selection', 'How do businesses choose office space?', NULL, 'Businesses consider location, size, layout, cost, accessibility, employee needs, branding, growth plans, and lease terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(670, 'Commercial Real Estate', 'retail_property', 'What should I know before buying retail property?', NULL, 'Retail property decisions should consider customer traffic, visibility, tenant mix, location, operating costs, and market demand.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(671, 'Commercial Real Estate', 'industrial_property', 'What is industrial real estate?', NULL, 'Industrial real estate includes warehouses, manufacturing facilities, distribution centers, logistics properties, and other spaces used for production or storage.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(672, 'Commercial Real Estate', 'mixed_use_property', 'What is a mixed-use development?', NULL, 'A mixed-use property combines multiple uses such as residential, retail, office, entertainment, or community spaces within one development.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(673, 'Commercial Real Estate', 'commercial_property_risk', 'What are risks of commercial real estate investing?', NULL, 'Risks may include vacancies, market changes, tenant issues, financing challenges, operating costs, and economic conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(674, 'Commercial Real Estate', 'commercial_real_estate_agent', 'What does a commercial real estate agent do?', NULL, 'A commercial real estate agent helps businesses and investors buy, sell, lease, analyze, and negotiate commercial property transactions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(675, 'Commercial Real Estate', 'commercial_real_estate_future', 'What is the future of commercial real estate?', NULL, 'Commercial real estate continues to evolve due to technology, changing work patterns, online commerce, demographics, and new business models.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:18', '2026-08-03 07:46:18'),
(676, 'Negotiation', 'making_home_offer', 'How do I make an offer on a home?', NULL, 'Making an offer involves determining a suitable price, reviewing market conditions, including appropriate terms, and submitting a formal offer through the required process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(677, 'Negotiation', 'offer_price', 'How do I decide what price to offer?', NULL, 'Offer price decisions should consider comparable sales, property condition, market competition, seller situation, budget, and negotiation strategy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(678, 'Negotiation', 'lowball_offer', 'What is a lowball offer?', NULL, 'A lowball offer is an offer significantly below the asking price. It may be accepted, rejected, or used as a starting point for negotiation depending on circumstances.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(679, 'Negotiation', 'strong_home_offer', 'What makes a strong home offer?', NULL, 'A strong offer may include competitive pricing, solid financing, favorable terms, flexibility, and fewer conditions that create uncertainty for the seller.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(680, 'Negotiation', 'multiple_offer_situation', 'What happens when there are multiple offers on a home?', NULL, 'In multiple-offer situations, sellers may compare price, terms, financing strength, contingencies, timing, and overall buyer reliability.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(681, 'Negotiation', 'best_offer_strategy', 'Should I always offer the highest price?', NULL, 'The highest price is not always the only factor. Sellers may consider terms, certainty, timing, and the overall strength of the offer.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(682, 'Negotiation', 'counter_offer', 'What is a counteroffer in real estate?', NULL, 'A counteroffer is a response to an offer where the seller or buyer proposes different terms, conditions, or pricing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(683, 'Negotiation', 'counter_offer_response', 'How should I respond to a counteroffer?', NULL, 'Review the revised terms carefully, consider your goals, evaluate market conditions, and decide whether to accept, reject, or make another counteroffer.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(684, 'Negotiation', 'seller_negotiation', 'How should sellers negotiate offers?', NULL, 'Sellers should evaluate price, terms, buyer qualifications, timing, contingencies, and overall transaction strength before accepting an offer.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(685, 'Negotiation', 'buyer_negotiation', 'How can buyers negotiate effectively?', NULL, 'Buyers can negotiate by understanding market conditions, preparing strong offers, knowing their limits, and focusing on important terms beyond price.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(686, 'Negotiation', 'contingency_negotiation', 'What are contingencies in a real estate offer?', NULL, 'Contingencies are conditions that must be met for a transaction to proceed, such as financing approval, inspections, or property-related requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(687, 'Negotiation', 'remove_contingencies', 'Should I remove contingencies to make my offer stronger?', NULL, 'Removing contingencies may make an offer more attractive but can increase buyer risk. Decisions should consider personal circumstances and professional advice.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(688, 'Negotiation', 'inspection_negotiation', 'Can I negotiate after a home inspection?', NULL, 'Yes, buyers may negotiate repairs, credits, price adjustments, or other solutions depending on the inspection results and agreement terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(689, 'Negotiation', 'repair_credit', 'What is a repair credit?', NULL, 'A repair credit is an amount the seller agrees to provide toward buyer expenses instead of completing certain repairs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(690, 'Negotiation', 'closing_date_negotiation', 'Can the closing date be negotiated?', NULL, 'Yes, buyers and sellers can often negotiate closing dates based on schedules, financing timelines, and transaction needs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(691, 'Negotiation', 'seller_concessions', 'What are seller concessions?', NULL, 'Seller concessions are costs or credits the seller agrees to provide to help the buyer with certain transaction expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(692, 'Negotiation', 'price_negotiation_seller', 'How do sellers negotiate home price?', NULL, 'Sellers negotiate price by considering market data, buyer demand, property condition, timing goals, and competing offers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(693, 'Negotiation', 'price_negotiation_buyer', 'How do buyers negotiate a lower price?', NULL, 'Buyers may negotiate using market data, property condition, inspection findings, comparable sales, and seller motivations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(694, 'Negotiation', 'emotional_negotiation', 'How do emotions affect real estate negotiations?', NULL, 'Real estate decisions can be emotional. Staying focused on goals, facts, and strategy can help create better outcomes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(695, 'Negotiation', 'negotiation_agent_role', 'How does a real estate agent help with negotiation?', NULL, 'Agents provide market knowledge, communication support, strategy, experience, and guidance during offer and counteroffer discussions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(696, 'Negotiation', 'accept_offer', 'When should a seller accept an offer?', NULL, 'Sellers should evaluate whether the offer meets their goals regarding price, terms, timing, certainty, and overall transaction benefits.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(697, 'Negotiation', 'reject_offer', 'Can a seller reject an offer?', NULL, 'Yes, sellers may reject offers, negotiate changes, or choose another buyer depending on their circumstances and agreements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(698, 'Negotiation', 'expired_offer', 'What happens if an offer expires?', NULL, 'If an offer expires without acceptance, it may no longer be valid unless the parties agree to extend or modify the terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(699, 'Negotiation', 'verbal_offer', 'Are verbal offers valid in real estate?', NULL, 'Real estate offer requirements vary by location, but many transactions require written agreements to be legally enforceable.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(700, 'Negotiation', 'deal_fall_through', 'Why do real estate deals fall apart?', NULL, 'Deals may fail due to financing issues, inspection problems, appraisal concerns, contract disagreements, title issues, or changes in buyer or seller circumstances.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:46:46', '2026-08-03 07:46:46'),
(701, 'Closing Process', 'what_is_closing', 'What is closing in real estate?', NULL, 'Closing is the final stage of a real estate transaction when documents are signed, funds are transferred, and ownership is officially transferred to the buyer.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(702, 'Closing Process', 'closing_day', 'What happens on closing day?', NULL, 'On closing day, parties complete required paperwork, verify transaction details, transfer funds, and finalize ownership transfer according to the agreed process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(703, 'Closing Process', 'closing_documents', 'What documents are signed at closing?', NULL, 'Closing documents may include purchase agreements, loan documents, disclosures, title documents, settlement statements, and ownership transfer paperwork.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(704, 'Closing Process', 'settlement_statement', 'What is a settlement statement?', NULL, 'A settlement statement provides a detailed breakdown of transaction costs, credits, fees, payments, and financial adjustments for buyers and sellers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(705, 'Closing Process', 'final_walkthrough', 'What is a final walkthrough?', NULL, 'A final walkthrough allows the buyer to verify that the property condition matches the agreement before completing the purchase.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(706, 'Closing Process', 'keys_transfer', 'When do buyers receive the keys?', NULL, 'Keys are typically transferred after closing is completed and ownership transfer requirements have been satisfied according to the transaction terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(707, 'Closing Process', 'deed_recording', 'What happens after the deed is recorded?', NULL, 'Once the deed is recorded, the ownership transfer becomes part of the official public record according to local procedures.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(708, 'Closing Process', 'title_transfer', 'How is property ownership transferred?', NULL, 'Ownership transfer occurs through legal documents such as deeds and recording procedures required by local authorities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(709, 'Closing Process', 'closing_delay', 'Why can a real estate closing be delayed?', NULL, 'Closings may be delayed due to financing issues, document problems, title concerns, appraisal issues, inspections, or scheduling challenges.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(710, 'Closing Process', 'closing_cost_payment', 'When are closing costs paid?', NULL, 'Closing costs are typically paid at closing, but exact timing and responsibility depend on the transaction agreement and local practices.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(711, 'Closing Process', 'buyer_after_closing', 'What should buyers do after closing?', NULL, 'After closing, buyers should organize documents, update accounts, arrange utilities, secure insurance, maintain the property, and plan future upkeep.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(712, 'Closing Process', 'seller_after_closing', 'What should sellers do after closing?', NULL, 'After closing, sellers should keep transaction records, complete move-out responsibilities, update addresses, and manage proceeds according to their plans.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(713, 'Closing Process', 'moving_into_new_home', 'What should I do when moving into a new home?', NULL, 'New homeowners should inspect the property, change locks if needed, set up utilities, locate important systems, and create a maintenance plan.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(714, 'Closing Process', 'change_home_address', 'How do I update my address after moving?', NULL, 'Update your address with government agencies, financial institutions, employers, insurance providers, subscriptions, and important contacts.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(715, 'Closing Process', 'home_security_after_purchase', 'Should I change locks after buying a home?', NULL, 'Many homeowners choose to change locks or update security systems after purchasing a property for additional security and control.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(716, 'Closing Process', 'home_maintenance_schedule', 'Why is a home maintenance schedule important?', NULL, 'A maintenance schedule helps protect the property, prevent expensive repairs, improve safety, and maintain long-term value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(717, 'Closing Process', 'new_home_warranty', 'What should I know about warranties after buying a home?', NULL, 'Review warranties for appliances, systems, renovations, and new construction items to understand coverage and claim procedures.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(718, 'Closing Process', 'property_records', 'What property records should I keep?', NULL, 'Keep important records such as purchase documents, deed information, mortgage records, insurance policies, warranties, receipts, and improvement records.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(719, 'Closing Process', 'home_improvement_records', 'Why should I keep records of home improvements?', NULL, 'Improvement records can help with maintenance planning, insurance claims, future selling decisions, and documenting property upgrades.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(720, 'Closing Process', 'property_insurance_update', 'Should I update insurance after buying a home?', NULL, 'Yes, homeowners should confirm appropriate insurance coverage begins according to the purchase agreement and ownership requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(721, 'Closing Process', 'utility_transfer', 'How do I transfer utilities when buying a home?', NULL, 'Contact utility providers before moving to arrange service transfers, account setup, and final readings when needed.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(722, 'Closing Process', 'new_home_neighbors', 'Should I meet my new neighbors after moving?', NULL, 'Building relationships with neighbors can help create community connections and provide useful local information.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(723, 'Closing Process', 'home_improvement_after_purchase', 'What improvements should I make after buying a home?', NULL, 'Prioritize improvements based on safety, maintenance needs, energy efficiency, lifestyle preferences, and budget.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(724, 'Closing Process', 'property_tax_after_purchase', 'When do property taxes start after buying a home?', NULL, 'Property tax responsibility begins according to local rules and the closing agreement. Buyers should understand upcoming tax obligations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(725, 'Closing Process', 'first_year_homeowner', 'What should first-year homeowners focus on?', NULL, 'First-year homeowners should learn their home systems, maintain the property, build savings for repairs, review insurance, and plan improvements carefully.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:09', '2026-08-03 07:47:09'),
(726, 'Real Estate Marketing', 'property_marketing', 'How do real estate agents market properties?', NULL, 'Agents market properties through online listings, professional photography, videos, social media, advertising, networking, open houses, and targeted campaigns.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(727, 'Real Estate Marketing', 'seller_marketing_plan', 'What is a real estate marketing plan for sellers?', NULL, 'A marketing plan outlines how a property will be promoted, including pricing strategy, online exposure, media, buyer targeting, and communication methods.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(728, 'Real Estate Marketing', 'professional_photography', 'Why are professional photos important when selling a home?', NULL, 'Professional photos help present a property attractively, create stronger first impressions, and encourage more buyers to schedule viewings.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(729, 'Real Estate Marketing', 'real_estate_video', 'Why should sellers use property videos?', NULL, 'Property videos allow buyers to experience the home layout, features, and lifestyle benefits before visiting in person.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(730, 'Real Estate Marketing', 'social_media_real_estate', 'How do agents use social media for real estate?', NULL, 'Agents use social media to showcase properties, educate audiences, build relationships, promote services, and generate leads.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(731, 'Real Estate Marketing', 'real_estate_branding', 'Why is branding important for real estate agents?', NULL, 'Strong branding helps agents build recognition, establish trust, communicate their value, and differentiate themselves in competitive markets.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(732, 'Real Estate Marketing', 'real_estate_lead_generation', 'What is lead generation in real estate?', NULL, 'Lead generation is the process of attracting potential buyers, sellers, renters, or investors who may need real estate services.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(733, 'Real Estate Marketing', 'real_estate_website', 'Why should a real estate agent have a website?', NULL, 'A website helps agents establish credibility, showcase listings, provide information, capture leads, and provide resources for clients.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(734, 'Real Estate Marketing', 'seo_real_estate', 'What is SEO for real estate?', NULL, 'Real estate SEO improves online visibility by optimizing websites and content so potential clients can find services through search engines.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(735, 'Real Estate Marketing', 'real_estate_blog', 'Why should agents create real estate content?', NULL, 'Content helps educate clients, improve online visibility, demonstrate expertise, answer common questions, and build trust.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(736, 'Real Estate Marketing', 'email_marketing_real_estate', 'How does email marketing help real estate agents?', NULL, 'Email marketing helps agents stay connected with leads, share updates, provide market information, and maintain relationships with past clients.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(737, 'Real Estate Marketing', 'open_house_marketing', 'How do agents promote open houses?', NULL, 'Open houses may be promoted through online listings, social media, signage, email campaigns, local advertising, and direct communication.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(738, 'Real Estate Marketing', 'property_description', 'What makes a good property description?', NULL, 'A strong property description highlights important features, benefits, location advantages, lifestyle appeal, and unique selling points.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(739, 'Real Estate Marketing', 'virtual_staging_marketing', 'How does virtual staging help sell properties?', NULL, 'Virtual staging helps buyers visualize how spaces can be used and may improve online listing appeal.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(740, 'Real Estate Marketing', 'drone_marketing', 'Why use drone photography for real estate?', NULL, 'Drone photography can showcase property size, land features, surroundings, views, and location advantages.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(741, 'Real Estate Marketing', 'targeted_advertising', 'What is targeted real estate advertising?', NULL, 'Targeted advertising focuses marketing efforts toward specific audiences based on location, interests, demographics, or buyer characteristics.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(742, 'Real Estate Marketing', 'real_estate_reviews', 'Why are client reviews important for agents?', NULL, 'Reviews help build credibility, demonstrate customer satisfaction, and influence potential clients when choosing an agent.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(743, 'Real Estate Marketing', 'referral_business', 'How important are referrals in real estate?', NULL, 'Referrals are an important source of business because they are based on trust and recommendations from previous clients or professional contacts.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(744, 'Real Estate Marketing', 'real_estate_networking', 'Why is networking important for real estate agents?', NULL, 'Networking helps agents build relationships, find opportunities, generate referrals, and connect with potential clients and professionals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(745, 'Real Estate Marketing', 'listing_presentation', 'What is a listing presentation?', NULL, 'A listing presentation is a meeting where an agent explains their marketing strategy, pricing approach, services, and plan for selling a property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(746, 'Real Estate Marketing', 'real_estate_ad_budget', 'How much should agents spend on marketing?', NULL, 'Marketing budgets vary based on business goals, market conditions, services offered, audience, and available resources.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(747, 'Real Estate Marketing', 'buyer_marketing', 'How do agents attract home buyers?', NULL, 'Agents attract buyers through listings, online marketing, educational content, networking, advertising, and personalized property searches.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(748, 'Real Estate Marketing', 'seller_leads', 'How do agents find homeowners who want to sell?', NULL, 'Agents generate seller leads through referrals, market outreach, online presence, community involvement, advertising, and relationship building.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(749, 'Real Estate Marketing', 'real_estate_crm_marketing', 'How does a CRM help real estate marketing?', NULL, 'A CRM helps organize leads, track communication, manage follow-ups, automate tasks, and improve client relationship management.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(750, 'Real Estate Marketing', 'ai_real_estate_marketing', 'How can AI improve real estate marketing?', NULL, 'AI can help create content, analyze data, automate communication, personalize marketing, and improve efficiency in real estate operations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:47:36', '2026-08-03 07:47:36'),
(751, 'Buyer Psychology', 'buyer_home_fear', 'Why am I nervous about buying a home?', NULL, 'Buying a home is a major financial and personal decision. Many buyers feel uncertain because of costs, commitment, market conditions, and the complexity of the process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(752, 'Buyer Psychology', 'first_home_emotions', 'What emotions do first-time buyers experience?', NULL, 'First-time buyers may experience excitement, stress, uncertainty, and confidence changes as they navigate a major life decision.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(753, 'Buyer Psychology', 'choosing_right_home', 'How do I know if a home is right for me?', NULL, 'A home should match your budget, lifestyle, location preferences, future plans, comfort level, and long-term goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(754, 'Buyer Psychology', 'dream_home_vs_budget', 'Should I buy my dream home or stay within my budget?', NULL, 'Balancing lifestyle goals with financial responsibility is important. A sustainable purchase should fit your current and future financial situation.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(755, 'Buyer Psychology', 'buyer_regret', 'How can I avoid buyer’s remorse?', NULL, 'Reduce regret by researching carefully, understanding costs, inspecting the property, considering long-term needs, and making decisions based on facts rather than pressure.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(756, 'Buyer Psychology', 'home_search_overwhelmed', 'Why does home searching feel overwhelming?', NULL, 'The number of choices, financial decisions, market competition, and emotional factors can make the process challenging. A clear plan can help.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(757, 'Buyer Psychology', 'neighborhood_choice', 'How do I choose the right neighborhood?', NULL, 'Consider safety, schools, commute, amenities, lifestyle preferences, future development, property values, and community environment.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(758, 'Buyer Psychology', 'location_importance', 'Is location more important than the house?', NULL, 'Location strongly affects convenience, lifestyle, future value, and resale potential. The importance depends on individual priorities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(759, 'Buyer Psychology', 'compromise_home_buying', 'What should I compromise on when buying a home?', NULL, 'Buyers often prioritize must-have features and remain flexible on items that can be changed, such as finishes, paint, or certain design preferences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(760, 'Buyer Psychology', 'must_have_features', 'How do I identify my must-have home features?', NULL, 'Separate needs from wants by considering daily lifestyle, family requirements, work needs, budget, and future plans.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(761, 'Buyer Psychology', 'home_comparison', 'Why do homes look different online than in person?', NULL, 'Photos, angles, lighting, and staging can affect perception. Visiting the property provides a more accurate understanding.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(762, 'Buyer Psychology', 'buying_competition_stress', 'How do I handle competition from other buyers?', NULL, 'Prepare financially, understand market conditions, work with professionals, and focus on making a strong but comfortable offer.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(763, 'Buyer Psychology', 'fear_of_missing_out', 'Should I buy quickly because I fear missing out?', NULL, 'Major purchases should be based on affordability, suitability, and careful evaluation rather than pressure or fear.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(764, 'Buyer Psychology', 'market_pressure', 'Should I buy because everyone else is buying?', NULL, 'Real estate decisions should be based on your financial readiness, goals, and personal circumstances rather than external pressure.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(765, 'Buyer Psychology', 'home_showing_impression', 'What should I notice during a home showing?', NULL, 'Pay attention to layout, condition, neighborhood, noise levels, natural light, storage, maintenance needs, and how the home feels.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(766, 'Buyer Psychology', 'future_home_needs', 'How do I consider future needs when buying?', NULL, 'Think about possible changes in family size, work situation, lifestyle, finances, accessibility, and long-term plans.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02');
INSERT INTO `real_estate_faqs` (`id`, `category`, `intent_name`, `user_question`, `question_variations`, `answer`, `required_information`, `agent_handoff`, `keywords`, `language`, `status`, `created_at`, `updated_at`) VALUES
(767, 'Buyer Psychology', 'online_reviews_home', 'Should I rely on online reviews when choosing a home area?', NULL, 'Online reviews can provide insights, but buyers should also visit neighborhoods, research data, and evaluate personal priorities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(768, 'Buyer Psychology', 'buyer_decision_process', 'How do buyers make a final home decision?', NULL, 'Buyers usually evaluate price, location, condition, financing, lifestyle fit, future value, and emotional connection before deciding.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(769, 'Buyer Psychology', 'second_opinion_home', 'Should I get another opinion before buying?', NULL, 'Many buyers benefit from discussing decisions with trusted professionals, family members, or advisors before making a major commitment.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(770, 'Buyer Psychology', 'agent_buying_guidance', 'How can a real estate agent help me make decisions?', NULL, 'Agents provide market knowledge, property information, negotiation support, and guidance throughout the buying process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(771, 'Buyer Psychology', 'perfect_home_search', 'Will I find a perfect home?', NULL, 'No property is perfect. Successful buyers usually focus on finding a home that meets their most important needs and priorities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(772, 'Buyer Psychology', 'home_buying_confidence', 'How can I feel more confident buying a home?', NULL, 'Confidence comes from preparation, financial planning, market education, professional guidance, and understanding the process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(773, 'Buyer Psychology', 'buyer_mistakes', 'What mistakes do buyers commonly make?', NULL, 'Common mistakes include ignoring budgets, skipping inspections, rushing decisions, overlooking future needs, and failing to research costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(774, 'Buyer Psychology', 'emotional_home_purchase', 'How do emotions affect home buying decisions?', NULL, 'Emotions naturally influence buying decisions, but combining feelings with financial analysis and practical evaluation leads to better choices.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(775, 'Buyer Psychology', 'trust_real_estate_agent', 'How do I know I can trust my real estate agent?', NULL, 'Trust is built through communication, transparency, experience, professionalism, market knowledge, and putting client interests first.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:02', '2026-08-03 07:48:02'),
(776, 'Seller Psychology', 'seller_emotions', 'Why is selling a home emotional?', NULL, 'A home often represents memories, achievements, and personal experiences. Emotional attachment is common when making a major transition.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(777, 'Seller Psychology', 'letting_go_home', 'How do I prepare emotionally to sell my home?', NULL, 'Focus on future goals, preserve memories through photos, organize the transition, and view the sale as the next step in your journey.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(778, 'Seller Psychology', 'home_attachment_pricing', 'Can emotional attachment affect my selling price?', NULL, 'Yes, emotional attachment may lead owners to overestimate value. Market data and professional guidance help determine realistic pricing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(779, 'Seller Psychology', 'overprice_home', 'Why do some sellers overprice their homes?', NULL, 'Sellers may overprice due to emotional value, incorrect comparisons, financial goals, or misunderstanding current market conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(780, 'Seller Psychology', 'correct_home_price', 'How do I choose the right asking price?', NULL, 'The right price is based on comparable sales, market conditions, property condition, location, buyer demand, and professional market analysis.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(781, 'Seller Psychology', 'price_too_high', 'What happens if my home is priced too high?', NULL, 'An overpriced home may receive fewer showings, stay longer on the market, and require future price adjustments.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(782, 'Seller Psychology', 'seller_market_expectation', 'How should sellers set expectations in today’s market?', NULL, 'Sellers should understand local conditions, buyer behavior, competition, timing, and realistic pricing strategies.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(783, 'Seller Psychology', 'sell_or_wait', 'Should I sell now or wait?', NULL, 'The decision depends on personal goals, finances, market conditions, timing needs, and future plans.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(784, 'Seller Psychology', 'seller_market_timing', 'Is timing important when selling a home?', NULL, 'Timing can influence buyer activity and competition, but preparation, pricing, and marketing strategy are also major factors.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(785, 'Seller Psychology', 'choose_listing_agent', 'How do I choose the right listing agent?', NULL, 'Choose an agent based on experience, local knowledge, communication style, marketing ability, negotiation skills, and client service.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(786, 'Seller Psychology', 'seller_agent_interview', 'What should I ask a real estate agent before listing my home?', NULL, 'Ask about pricing strategy, marketing plan, experience, communication process, fees, transaction support, and expected timeline.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(787, 'Seller Psychology', 'seller_marketing_expectation', 'What should I expect from my agent’s marketing?', NULL, 'Expect professional presentation, online exposure, communication, buyer outreach, feedback collection, and strategy adjustments when needed.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(788, 'Seller Psychology', 'home_showing_preparation', 'How should I prepare emotionally for home showings?', NULL, 'Understand that buyers are evaluating the property, not your personal memories. Focus on presenting the home effectively.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(789, 'Seller Psychology', 'negative_buyer_feedback', 'How should I handle negative feedback from buyers?', NULL, 'Feedback can provide useful information about pricing, condition, or presentation. Use it to improve the selling strategy when appropriate.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(790, 'Seller Psychology', 'seller_rejection_offer', 'How should sellers handle rejected offers?', NULL, 'A rejected offer can provide insight into buyer interest and market response. Sellers should evaluate options objectively and continue the strategy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(791, 'Seller Psychology', 'multiple_offer_seller', 'How should sellers choose between multiple offers?', NULL, 'Sellers should compare price, financing strength, contingencies, timing, and overall reliability rather than focusing only on price.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(792, 'Seller Psychology', 'seller_negotiation_emotions', 'How can sellers avoid emotional negotiation?', NULL, 'Focus on goals, market facts, transaction terms, and professional advice instead of reacting emotionally during negotiations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(793, 'Seller Psychology', 'declutter_before_sale', 'Why is decluttering important before selling?', NULL, 'Decluttering helps buyers visualize the space, improves presentation, and can make the property appear larger and more appealing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(794, 'Seller Psychology', 'staging_decision', 'Should every seller stage their home?', NULL, 'Staging decisions depend on property condition, market expectations, budget, and the potential impact on buyer interest.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(795, 'Seller Psychology', 'seller_common_mistakes', 'What mistakes do sellers commonly make?', NULL, 'Common mistakes include overpricing, poor preparation, limited marketing, ignoring feedback, and choosing an agent without proper research.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(796, 'Seller Psychology', 'seller_expect_fast_sale', 'Why did my home not sell quickly?', NULL, 'Possible reasons include pricing, condition, marketing exposure, buyer demand, competition, or market changes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(797, 'Seller Psychology', 'selling_family_home', 'How do I sell a family home with many memories?', NULL, 'Recognize the emotional importance while focusing on practical steps, future goals, and creating a smooth transition.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(798, 'Seller Psychology', 'seller_confidence', 'How can I feel confident selling my home?', NULL, 'Confidence comes from preparation, realistic expectations, market knowledge, professional support, and understanding the process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(799, 'Seller Psychology', 'seller_control_process', 'How much control do sellers have during the selling process?', NULL, 'Sellers control many decisions including pricing strategy, timing, preparation, marketing choices, and offer decisions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(800, 'Seller Psychology', 'successful_home_sale', 'What makes a successful home sale?', NULL, 'A successful sale combines proper pricing, strong marketing, good preparation, effective negotiation, and a smooth closing process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:26', '2026-08-03 07:48:26'),
(801, 'Compliance & Ethics', 'real_estate_ethics', 'What are real estate ethics?', NULL, 'Real estate ethics are professional principles that guide agents and professionals to act honestly, fairly, transparently, and responsibly with clients and the public.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(802, 'Compliance & Ethics', 'agent_fiduciary_duty', 'What is fiduciary duty in real estate?', NULL, 'Fiduciary duty means an agent has responsibilities to act in the client’s best interest, maintain confidentiality, provide loyalty, and follow professional obligations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(803, 'Compliance & Ethics', 'fair_housing', 'What is fair housing?', NULL, 'Fair housing refers to laws and practices designed to ensure people have equal access to housing opportunities without unlawful discrimination.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(804, 'Compliance & Ethics', 'housing_discrimination', 'What is housing discrimination?', NULL, 'Housing discrimination occurs when someone is treated unfairly in housing-related activities based on protected characteristics under applicable laws.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(805, 'Compliance & Ethics', 'equal_opportunity_housing', 'What does equal opportunity housing mean?', NULL, 'Equal opportunity housing means individuals have the right to seek and obtain housing without unlawful barriers or discrimination.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(806, 'Compliance & Ethics', 'property_disclosure', 'What are property disclosures?', NULL, 'Property disclosures provide important information about known property conditions, issues, or facts that may affect a buyer’s decision.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(807, 'Compliance & Ethics', 'seller_disclosure', 'What must sellers disclose when selling a home?', NULL, 'Disclosure requirements vary by location but generally involve sharing known material facts about the property condition.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(808, 'Compliance & Ethics', 'material_fact', 'What is a material fact in real estate?', NULL, 'A material fact is information that could influence a reasonable buyer’s decision about purchasing a property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(809, 'Compliance & Ethics', 'agent_confidentiality', 'What information must a real estate agent keep confidential?', NULL, 'Agents generally protect confidential client information according to professional duties, agreements, and applicable laws.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(810, 'Compliance & Ethics', 'client_privacy', 'How do real estate professionals protect client privacy?', NULL, 'Professionals protect privacy by handling personal information responsibly, using secure systems, and following legal requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(811, 'Compliance & Ethics', 'real_estate_fraud', 'What is real estate fraud?', NULL, 'Real estate fraud involves intentionally providing false information, misrepresentation, or illegal actions related to property transactions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(812, 'Compliance & Ethics', 'avoid_real_estate_fraud', 'How can buyers and sellers avoid real estate fraud?', NULL, 'Work with qualified professionals, verify information, review documents carefully, and avoid unusual requests or pressure tactics.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(813, 'Compliance & Ethics', 'agent_misrepresentation', 'What is misrepresentation in real estate?', NULL, 'Misrepresentation occurs when false, misleading, or incomplete information is provided about a property, transaction, or service.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(814, 'Compliance & Ethics', 'truthful_marketing', 'Why is truthful marketing important in real estate?', NULL, 'Accurate marketing builds trust, protects consumers, supports fair transactions, and helps professionals comply with regulations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(815, 'Compliance & Ethics', 'real_estate_contract_ethics', 'Why are contracts important in real estate?', NULL, 'Contracts clearly define responsibilities, obligations, terms, and protections for parties involved in a transaction.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(816, 'Compliance & Ethics', 'license_violation', 'What happens if a real estate agent violates regulations?', NULL, 'Consequences vary by location and violation but may include disciplinary action, fines, license restrictions, or other penalties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(817, 'Compliance & Ethics', 'agent_training_requirements', 'Why do real estate agents need ongoing training?', NULL, 'Ongoing training helps agents understand changing laws, market practices, technology, ethics, and professional responsibilities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(818, 'Compliance & Ethics', 'professional_real_estate_service', 'What makes a real estate professional trustworthy?', NULL, 'Trustworthy professionals communicate clearly, act ethically, provide accurate information, protect client interests, and maintain professionalism.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(819, 'Compliance & Ethics', 'dual_agency', 'What is dual agency in real estate?', NULL, 'Dual agency occurs when one agent or brokerage represents both buyer and seller in the same transaction where permitted by applicable rules.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(820, 'Compliance & Ethics', 'agency_relationship', 'What is an agency relationship in real estate?', NULL, 'An agency relationship defines how a real estate professional represents and owes duties to a client during a transaction.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(821, 'Compliance & Ethics', 'real_estate_consumer_rights', 'What rights do real estate consumers have?', NULL, 'Consumer rights vary by location but generally include fair treatment, accurate information, transparency, and access to required disclosures.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(822, 'Compliance & Ethics', 'transaction_transparency', 'Why is transparency important in real estate transactions?', NULL, 'Transparency helps parties make informed decisions, reduces misunderstandings, and builds confidence throughout the process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(823, 'Compliance & Ethics', 'conflict_of_interest', 'What is a conflict of interest in real estate?', NULL, 'A conflict of interest occurs when personal interests may interfere with professional responsibilities or client objectives.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(824, 'Compliance & Ethics', 'report_unethical_agent', 'How can I report unethical real estate behavior?', NULL, 'Reporting procedures vary by location but may involve professional associations, licensing authorities, regulators, or legal channels.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(825, 'Compliance & Ethics', 'ethical_ai_real_estate', 'How should AI be used ethically in real estate?', NULL, 'AI should support professionals while protecting privacy, avoiding discrimination, providing accurate information, and maintaining human oversight.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:48:56', '2026-08-03 07:48:56'),
(826, 'Luxury Real Estate', 'what_is_luxury_real_estate', 'What is luxury real estate?', NULL, 'Luxury real estate refers to high-value properties that typically offer premium locations, exceptional design, unique features, superior finishes, and exclusive amenities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(827, 'Luxury Real Estate', 'luxury_home_features', 'What features are common in luxury homes?', NULL, 'Luxury homes may include custom architecture, premium materials, smart technology, pools, expansive views, entertainment spaces, private amenities, and high-end finishes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(828, 'Luxury Real Estate', 'luxury_home_price', 'What makes a home a luxury property?', NULL, 'A luxury property is defined by factors such as location, scarcity, design quality, features, size, privacy, and market demand rather than price alone.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(829, 'Luxury Real Estate', 'buy_luxury_home', 'How do I buy a luxury home?', NULL, 'Buying luxury property involves identifying priorities, working with experienced professionals, evaluating unique features, reviewing finances, and conducting detailed due diligence.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(830, 'Luxury Real Estate', 'sell_luxury_home', 'How do I sell a luxury property?', NULL, 'Selling luxury property requires specialized marketing, professional presentation, targeted buyer outreach, strategic pricing, and experienced negotiation.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(831, 'Luxury Real Estate', 'luxury_real_estate_agent', 'What does a luxury real estate agent do?', NULL, 'A luxury real estate agent specializes in serving high-end clients, marketing premium properties, managing privacy concerns, and handling complex negotiations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(832, 'Luxury Real Estate', 'luxury_property_marketing', 'How are luxury homes marketed differently?', NULL, 'Luxury marketing often includes premium photography, video tours, exclusive networks, targeted campaigns, storytelling, and personalized buyer outreach.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(833, 'Luxury Real Estate', 'private_listing', 'What is a private or off-market listing?', NULL, 'An off-market listing is a property marketed privately or through limited channels rather than being broadly advertised to the public.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(834, 'Luxury Real Estate', 'luxury_buyer_privacy', 'Why is privacy important in luxury real estate?', NULL, 'High-end buyers and sellers may value confidentiality, security, discretion, and controlled access during transactions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(835, 'Luxury Real Estate', 'luxury_home_valuation', 'How are luxury homes valued?', NULL, 'Luxury home valuation considers unique features, location, comparable properties, design quality, market demand, and scarcity factors.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(836, 'Luxury Real Estate', 'luxury_comparable_sales', 'Are luxury home comparisons difficult?', NULL, 'Yes, luxury properties are often unique, making valuation require specialized market knowledge and analysis of similar premium properties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(837, 'Luxury Real Estate', 'luxury_investment', 'Is luxury real estate a good investment?', NULL, 'Luxury real estate can provide appreciation and lifestyle benefits, but performance depends on location, market conditions, demand, and property characteristics.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(838, 'Luxury Real Estate', 'luxury_market_trends', 'What affects the luxury real estate market?', NULL, 'Luxury markets are influenced by economic conditions, wealth trends, interest rates, global demand, location desirability, and buyer preferences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(839, 'Luxury Real Estate', 'luxury_home_inspection', 'Do luxury homes need inspections?', NULL, 'Yes, luxury properties benefit from detailed inspections covering systems, construction quality, technology, amenities, and specialized features.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(840, 'Luxury Real Estate', 'luxury_home_security', 'What security features are common in luxury homes?', NULL, 'Luxury homes may include advanced security systems, gated access, surveillance, privacy features, and specialized safety technology.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(841, 'Luxury Real Estate', 'luxury_home_technology', 'What smart technologies are found in luxury homes?', NULL, 'Luxury properties may include automated lighting, climate control, entertainment systems, security, and integrated home management technology.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(842, 'Luxury Real Estate', 'luxury_home_staging', 'Should luxury homes be staged?', NULL, 'Luxury staging can highlight design, lifestyle appeal, space, and premium features to attract qualified buyers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(843, 'Luxury Real Estate', 'luxury_buyer_process', 'Is buying a luxury home different from buying a regular home?', NULL, 'Luxury transactions may involve more complex negotiations, privacy considerations, specialized inspections, and additional due diligence.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(844, 'Luxury Real Estate', 'international_luxury_buyers', 'Do international buyers purchase luxury real estate?', NULL, 'Yes, luxury markets often attract international buyers seeking investment opportunities, second homes, lifestyle properties, or diversification.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(845, 'Luxury Real Estate', 'luxury_second_home', 'Why do people buy luxury second homes?', NULL, 'Reasons include vacation use, lifestyle preferences, investment opportunities, privacy, and wealth planning.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(846, 'Luxury Real Estate', 'luxury_home_location', 'Why is location critical in luxury real estate?', NULL, 'Premium locations often provide exclusivity, lifestyle benefits, views, convenience, reputation, and long-term desirability.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(847, 'Luxury Real Estate', 'luxury_real_estate_network', 'Why are networks important in luxury real estate?', NULL, 'Strong networks help professionals access qualified buyers, private opportunities, market insights, and specialized services.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(848, 'Luxury Real Estate', 'luxury_negotiation', 'How are luxury property negotiations different?', NULL, 'Luxury negotiations may involve complex terms, privacy considerations, unique property values, and customized transaction structures.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(849, 'Luxury Real Estate', 'luxury_property_management', 'Do luxury homes require specialized management?', NULL, 'Many luxury properties benefit from specialized management for maintenance, security, amenities, and ongoing care.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(850, 'Luxury Real Estate', 'future_luxury_real_estate', 'What is the future of luxury real estate?', NULL, 'Luxury real estate continues evolving through technology, sustainability, changing lifestyles, global wealth trends, and demand for unique experiences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:23', '2026-08-03 07:49:23'),
(851, 'Real Estate Technology', 'ai_real_estate', 'How is AI changing real estate?', NULL, 'AI is helping real estate professionals automate tasks, analyze data, improve customer service, generate content, and make better-informed decisions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(852, 'Real Estate Technology', 'real_estate_chatbot', 'What is a real estate chatbot?', NULL, 'A real estate chatbot is an AI-powered assistant that answers questions, captures leads, provides property information, and helps clients navigate real estate services.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(853, 'Real Estate Technology', 'chatbot_benefits', 'What are the benefits of using a chatbot for real estate?', NULL, 'Chatbots can provide 24/7 responses, qualify leads, answer common questions, schedule appointments, and improve customer engagement.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(854, 'Real Estate Technology', 'ai_property_search', 'Can AI help buyers find homes?', NULL, 'AI can help analyze buyer preferences, recommend properties, organize searches, and improve the home discovery experience.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(855, 'Real Estate Technology', 'virtual_home_tour', 'What is a virtual home tour?', NULL, 'A virtual home tour allows buyers to explore a property digitally through interactive images, videos, or 3D experiences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(856, 'Real Estate Technology', '3d_home_tour', 'What are 3D property tours?', NULL, '3D tours provide interactive digital views of homes, allowing users to explore rooms and layouts remotely.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(857, 'Real Estate Technology', 'real_estate_crm', 'What is a real estate CRM?', NULL, 'A real estate CRM is a system that helps agents manage contacts, leads, communication, follow-ups, and client relationships.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(858, 'Real Estate Technology', 'crm_benefits_agents', 'How does CRM help real estate agents?', NULL, 'CRM systems help agents organize leads, automate follow-ups, track conversations, and improve relationship management.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(859, 'Real Estate Technology', 'real_estate_automation', 'What tasks can real estate automation handle?', NULL, 'Automation can assist with emails, reminders, lead management, appointment scheduling, marketing tasks, and routine administrative work.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(860, 'Real Estate Technology', 'digital_transaction', 'What is a digital real estate transaction?', NULL, 'A digital transaction uses technology for communication, document management, signatures, payments, and other parts of the real estate process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(861, 'Real Estate Technology', 'electronic_signature', 'Are electronic signatures used in real estate?', NULL, 'Electronic signatures are commonly used for many real estate documents where permitted by applicable laws and regulations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(862, 'Real Estate Technology', 'online_property_listing', 'How do online property listings work?', NULL, 'Online listings provide property details, photos, videos, pricing information, and contact options to help connect buyers and sellers.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(863, 'Real Estate Technology', 'property_data_analysis', 'How does technology help analyze real estate data?', NULL, 'Technology can process market trends, pricing information, property history, demographics, and other data to support decision-making.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(864, 'Real Estate Technology', 'predictive_real_estate_analysis', 'What is predictive analytics in real estate?', NULL, 'Predictive analytics uses data and algorithms to identify patterns, forecast trends, and support decisions about properties and markets.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(865, 'Real Estate Technology', 'smart_home_technology', 'What is smart home technology?', NULL, 'Smart home technology includes connected devices that control lighting, security, temperature, appliances, and other home functions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(866, 'Real Estate Technology', 'proptech', 'What is proptech?', NULL, 'Proptech refers to technology solutions designed to improve real estate buying, selling, renting, investing, management, and operations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(867, 'Real Estate Technology', 'real_estate_mobile_apps', 'How do mobile apps help real estate clients?', NULL, 'Mobile apps can help users search properties, communicate with agents, schedule appointments, save listings, and receive updates.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(868, 'Real Estate Technology', 'virtual_staging_ai', 'Can AI create virtual staging for homes?', NULL, 'AI-powered tools can help create digital furniture arrangements and visual improvements to help buyers imagine property possibilities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(869, 'Real Estate Technology', 'ai_property_valuation', 'Can AI estimate property values?', NULL, 'AI can analyze available data to provide valuation estimates, but professional evaluation and market expertise remain important.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(870, 'Real Estate Technology', 'voice_assistant_real_estate', 'Can voice assistants help with real estate?', NULL, 'Voice technology can help users search information, receive updates, schedule tasks, and interact with digital real estate services.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(871, 'Real Estate Technology', 'real_estate_data_security', 'How should real estate technology protect data?', NULL, 'Real estate technology should use appropriate security practices to protect personal information, transaction data, and client privacy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(872, 'Real Estate Technology', 'online_real_estate_consultation', 'Can I consult a real estate agent online?', NULL, 'Yes, many agents provide online consultations through video calls, chat, email, and digital communication tools.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(873, 'Real Estate Technology', 'ai_lead_qualification', 'How can AI qualify real estate leads?', NULL, 'AI can ask questions, identify buyer or seller needs, collect information, prioritize leads, and assist agents with follow-up.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(874, 'Real Estate Technology', 'future_real_estate_technology', 'What is the future of real estate technology?', NULL, 'Future trends may include advanced AI assistants, automation, immersive property experiences, smarter data analysis, and more digital transactions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(875, 'Real Estate Technology', 'human_agent_vs_ai', 'Will AI replace real estate agents?', NULL, 'AI can improve efficiency and support agents, but human skills such as negotiation, trust, local expertise, and relationship building remain valuable.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:49:46', '2026-08-03 07:49:46'),
(876, 'Relocation', 'real_estate_relocation', 'What is real estate relocation?', NULL, 'Real estate relocation involves helping individuals or families move from one location to another and find suitable housing in a new area.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(877, 'Relocation', 'moving_to_new_city', 'How do I buy a home in a new city?', NULL, 'Research neighborhoods, understand the local market, work with a knowledgeable agent, evaluate finances, and visit properties when possible.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(878, 'Relocation', 'out_of_state_home_buying', 'Can I buy a home from another state?', NULL, 'Yes, many buyers purchase homes remotely using online tools, local professionals, virtual tours, and digital transaction services.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(879, 'Relocation', 'relocation_real_estate_agent', 'What does a relocation real estate agent do?', NULL, 'A relocation agent helps clients understand new markets, find properties, evaluate neighborhoods, coordinate visits, and manage the buying or renting process.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(880, 'Relocation', 'remote_home_purchase', 'How does remote home buying work?', NULL, 'Remote purchases may involve virtual tours, online communication, electronic documents, inspections, and local professionals assisting throughout the transaction.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(881, 'Relocation', 'moving_company_selection', 'How do I choose a moving company?', NULL, 'Compare moving companies based on experience, licensing, services, pricing, reviews, availability, and insurance coverage.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(882, 'Relocation', 'moving_budget', 'How much should I budget for moving?', NULL, 'Moving costs depend on distance, household size, transportation, packing services, storage needs, and timing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(883, 'Relocation', 'relocation_package', 'What is a relocation package?', NULL, 'A relocation package is employer or organization support that may help cover moving expenses, temporary housing, travel, or other relocation costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(884, 'Relocation', 'corporate_relocation', 'What is corporate relocation?', NULL, 'Corporate relocation helps employees and their families move for work assignments and may include housing assistance and moving support.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(885, 'Relocation', 'choosing_new_neighborhood', 'How do I choose a neighborhood when relocating?', NULL, 'Consider commute, schools, safety, amenities, lifestyle, housing costs, community, future growth, and personal priorities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(886, 'Relocation', 'research_new_area', 'How do I research an area before moving?', NULL, 'Research housing prices, local services, transportation, employment opportunities, schools, community information, and market trends.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(887, 'Relocation', 'virtual_home_showing', 'Are virtual home showings useful for relocation buyers?', NULL, 'Virtual showings allow buyers to explore properties remotely and can help narrow choices before visiting in person.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(888, 'Relocation', 'relocation_home_inspection', 'Can inspections be done when buying remotely?', NULL, 'Yes, buyers can arrange professional inspections and receive reports, photos, and recommendations before completing a purchase.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(889, 'Relocation', 'temporary_housing', 'Should I rent before buying when relocating?', NULL, 'Renting temporarily can help buyers learn the area, understand neighborhoods, and make more informed purchasing decisions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(890, 'Relocation', 'relocation_timing', 'How early should I start planning a relocation?', NULL, 'Starting early provides time for research, budgeting, housing searches, moving arrangements, and reducing stress during the transition.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(891, 'Relocation', 'moving_with_family', 'What should families consider when relocating?', NULL, 'Families should consider schools, childcare, employment, community, healthcare, housing needs, and lifestyle changes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(892, 'Relocation', 'relocation_cost_hidden', 'What unexpected costs come with relocating?', NULL, 'Unexpected costs may include temporary housing, travel, storage, new services, deposits, repairs, and adjustments in living expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(893, 'Relocation', 'sell_before_relocating', 'Should I sell my home before relocating?', NULL, 'The decision depends on finances, timing, market conditions, housing plans, and personal circumstances.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(894, 'Relocation', 'buy_before_relocating', 'Should I buy a home before moving?', NULL, 'Buying before moving may provide stability but requires careful research, financial planning, and confidence in the new location.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(895, 'Relocation', 'relocation_market_difference', 'Why is the real estate market different in each city?', NULL, 'Each market is influenced by local supply, demand, economy, employment, regulations, geography, and community factors.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(896, 'Relocation', 'moving_checklist', 'What should be included in a relocation checklist?', NULL, 'A relocation checklist may include housing, finances, documents, utilities, moving arrangements, schools, services, and settling-in tasks.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(897, 'Relocation', 'change_utilities_after_move', 'How do I transfer utilities after relocating?', NULL, 'Contact utility providers before moving to arrange service activation, transfers, cancellations, and account updates.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(898, 'Relocation', 'new_city_real_estate_agent', 'Why should I use a local agent when relocating?', NULL, 'A local agent provides neighborhood knowledge, market insights, property information, and local connections that remote buyers may need.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(899, 'Relocation', 'relocation_stress', 'How can I reduce relocation stress?', NULL, 'Planning early, organizing tasks, using professional support, researching the area, and maintaining clear priorities can make relocation easier.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(900, 'Relocation', 'settling_new_home', 'How do I settle into a new community after moving?', NULL, 'Get familiar with local services, meet neighbors, explore the area, join activities, and build connections over time.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:13', '2026-08-03 07:50:13'),
(901, 'First-Time Investors', 'first_real_estate_investment', 'How do I make my first real estate investment?', NULL, 'Start by defining your goals, understanding your finances, researching markets, learning investment strategies, and evaluating suitable properties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(902, 'First-Time Investors', 'investment_goals', 'How do I set real estate investment goals?', NULL, 'Investment goals should define your desired income, timeline, risk level, growth expectations, and financial objectives.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(903, 'First-Time Investors', 'investment_budget', 'How much money do I need to start investing in real estate?', NULL, 'The amount needed varies depending on the property type, financing options, location, down payment requirements, and investment strategy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(904, 'First-Time Investors', 'rental_property_first', 'Is buying a rental property a good first investment?', NULL, 'A rental property can be a good starting point for some investors, but success depends on property selection, finances, management, and market conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(905, 'First-Time Investors', 'investment_property_search', 'How do I find an investment property?', NULL, 'Investors can find opportunities through agents, online listings, networking, market research, auctions, and investment communities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(906, 'First-Time Investors', 'investment_property_analysis', 'What should I analyze before buying an investment property?', NULL, 'Analyze purchase price, rental income, expenses, financing, location, tenant demand, repairs, taxes, and expected returns.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(907, 'First-Time Investors', 'rental_income_estimate', 'How do I estimate rental income?', NULL, 'Estimate rental income by researching comparable rentals, local demand, property features, vacancy rates, and market conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(908, 'First-Time Investors', 'investment_expenses', 'What expenses should real estate investors consider?', NULL, 'Expenses may include mortgage payments, taxes, insurance, repairs, maintenance, vacancies, management fees, and operating costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(909, 'First-Time Investors', 'vacancy_rate', 'What is vacancy rate in real estate investing?', NULL, 'Vacancy rate measures the percentage of time a rental property remains unoccupied and helps investors estimate potential income loss.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(910, 'First-Time Investors', 'property_management_first_time', 'Should first-time investors hire a property manager?', NULL, 'A property manager can help with tenants, maintenance, rent collection, and operations, but investors should consider costs and investment goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(911, 'First-Time Investors', 'tenant_selection', 'How do investors choose good tenants?', NULL, 'Tenant selection typically involves reviewing applications, income, rental history, references, and following applicable housing laws.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(912, 'First-Time Investors', 'investment_property_inspection', 'Should investors inspect rental properties?', NULL, 'Yes, inspections help identify repairs, risks, maintenance needs, and potential costs before purchasing.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(913, 'First-Time Investors', 'investment_location', 'What makes a good investment location?', NULL, 'Good investment locations often have rental demand, employment opportunities, population growth, amenities, transportation, and future potential.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(914, 'First-Time Investors', 'real_estate_investment_risk', 'What risks should new real estate investors know about?', NULL, 'Risks include vacancies, unexpected repairs, market changes, financing issues, tenant problems, and inaccurate financial assumptions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(915, 'First-Time Investors', 'investment_strategy', 'What real estate investment strategy should beginners use?', NULL, 'Beginners should choose strategies that match their finances, knowledge, risk tolerance, goals, and available time.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(916, 'First-Time Investors', 'buy_hold_strategy', 'What is the buy-and-hold strategy?', NULL, 'Buy-and-hold involves purchasing property and keeping it long term to generate income and benefit from potential appreciation.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(917, 'First-Time Investors', 'house_hacking', 'What is house hacking?', NULL, 'House hacking involves living in a property while generating rental income from additional units or rooms to reduce housing costs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(918, 'First-Time Investors', 'investment_financing', 'How can beginners finance real estate investments?', NULL, 'Financing options may include mortgages, investment loans, partnerships, private financing, or other approved funding methods.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(919, 'First-Time Investors', 'down_payment_investment', 'How much down payment is needed for an investment property?', NULL, 'Down payment requirements vary based on loan type, lender requirements, property type, borrower qualifications, and market conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(920, 'First-Time Investors', 'investment_cash_flow', 'Why is cash flow important for investors?', NULL, 'Cash flow helps investors understand whether property income can cover expenses and support long-term ownership.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36');
INSERT INTO `real_estate_faqs` (`id`, `category`, `intent_name`, `user_question`, `question_variations`, `answer`, `required_information`, `agent_handoff`, `keywords`, `language`, `status`, `created_at`, `updated_at`) VALUES
(921, 'First-Time Investors', 'investment_learning', 'How can I learn about real estate investing?', NULL, 'Learn through books, courses, market research, experienced professionals, networking, and analyzing real investment examples.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(922, 'First-Time Investors', 'real_estate_investment_agent', 'Should I work with an investment real estate agent?', NULL, 'An experienced investment agent can provide market knowledge, property analysis, opportunities, and transaction guidance.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(923, 'First-Time Investors', 'investment_portfolio_growth', 'How do investors grow a real estate portfolio?', NULL, 'Investors grow portfolios by reinvesting profits, acquiring additional properties, improving operations, and managing risk carefully.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(924, 'First-Time Investors', 'passive_income_real_estate', 'Can real estate create passive income?', NULL, 'Real estate can generate income, but most investments require planning, management, maintenance, and ongoing oversight.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(925, 'First-Time Investors', 'beginner_investor_mistakes', 'What mistakes do first-time real estate investors make?', NULL, 'Common mistakes include poor research, underestimating expenses, choosing the wrong property, ignoring cash flow, and failing to plan.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:36', '2026-08-03 07:50:36'),
(926, 'Mortgage & Financing', 'what_is_mortgage', 'What is a mortgage?', NULL, 'A mortgage is a loan used to purchase real estate where the property typically serves as security for the loan.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(927, 'Mortgage & Financing', 'how_mortgage_works', 'How does a mortgage work?', NULL, 'A mortgage allows buyers to purchase property by borrowing money and repaying the loan over time through scheduled payments.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(928, 'Mortgage & Financing', 'mortgage_payment', 'What is included in a mortgage payment?', NULL, 'A mortgage payment may include principal, interest, property taxes, homeowners insurance, and other costs depending on the loan arrangement.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(929, 'Mortgage & Financing', 'principal_vs_interest', 'What is the difference between mortgage principal and interest?', NULL, 'Principal is the amount borrowed, while interest is the cost charged by the lender for providing the loan.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(930, 'Mortgage & Financing', 'fixed_rate_mortgage', 'What is a fixed-rate mortgage?', NULL, 'A fixed-rate mortgage has an interest rate that remains the same throughout the agreed loan term.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(931, 'Mortgage & Financing', 'adjustable_rate_mortgage', 'What is an adjustable-rate mortgage?', NULL, 'An adjustable-rate mortgage has an interest rate that may change over time based on market conditions and loan terms.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(932, 'Mortgage & Financing', 'mortgage_preapproval', 'What is mortgage preapproval?', NULL, 'Mortgage preapproval is a lender’s evaluation indicating how much a borrower may qualify to borrow based on financial information.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(933, 'Mortgage & Financing', 'get_preapproved', 'How do I get preapproved for a mortgage?', NULL, 'Borrowers typically provide income, assets, debts, credit information, and documentation for lender review.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(934, 'Mortgage & Financing', 'credit_score_mortgage', 'How does credit score affect mortgage approval?', NULL, 'Credit scores can influence loan eligibility, interest rates, borrowing terms, and lender decisions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(935, 'Mortgage & Financing', 'improve_credit_before_home', 'How can I improve my credit before buying a home?', NULL, 'Improve credit by paying bills on time, reducing debt, checking reports for errors, and maintaining responsible financial habits.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(936, 'Mortgage & Financing', 'down_payment', 'What is a down payment?', NULL, 'A down payment is the upfront amount a buyer contributes toward purchasing a property, with the remaining cost typically financed through a loan.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(937, 'Mortgage & Financing', 'low_down_payment', 'Can I buy a home with a low down payment?', NULL, 'Some loan programs allow lower down payments depending on borrower qualifications, property type, and lender requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(938, 'Mortgage & Financing', 'mortgage_interest_rate', 'What determines mortgage interest rates?', NULL, 'Interest rates are influenced by economic conditions, market factors, lender policies, borrower qualifications, and loan characteristics.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(939, 'Mortgage & Financing', 'interest_rate_effect', 'How do interest rates affect buying power?', NULL, 'Higher rates generally increase borrowing costs and monthly payments, while lower rates may improve affordability.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(940, 'Mortgage & Financing', 'debt_to_income_ratio', 'What is debt-to-income ratio?', NULL, 'Debt-to-income ratio compares monthly debt obligations with income and is commonly considered during loan qualification.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(941, 'Mortgage & Financing', 'mortgage_affordability', 'How much mortgage can I afford?', NULL, 'Affordability depends on income, debts, savings, credit, interest rates, expenses, and financial goals.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(942, 'Mortgage & Financing', 'refinance_home', 'What does refinancing a mortgage mean?', NULL, 'Refinancing replaces an existing mortgage with a new loan, potentially changing the interest rate, payment, term, or loan structure.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(943, 'Mortgage & Financing', 'when_refinance', 'When should I consider refinancing?', NULL, 'Refinancing may be considered when financial goals, interest rates, loan terms, or personal circumstances make it beneficial.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(944, 'Mortgage & Financing', 'cash_out_refinance', 'What is cash-out refinancing?', NULL, 'Cash-out refinancing allows homeowners to replace an existing mortgage with a larger loan and receive the difference in funds, subject to qualifications.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(945, 'Mortgage & Financing', 'home_equity_loan', 'What is a home equity loan?', NULL, 'A home equity loan allows homeowners to borrow against available equity in their property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(946, 'Mortgage & Financing', 'heloc', 'What is a HELOC?', NULL, 'A home equity line of credit is a revolving credit option that allows borrowing against home equity within approved limits.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(947, 'Mortgage & Financing', 'investment_property_loan', 'Are mortgages different for investment properties?', NULL, 'Investment property loans may have different requirements, rates, down payments, and qualification standards compared with primary residence loans.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(948, 'Mortgage & Financing', 'commercial_financing', 'How does commercial real estate financing work?', NULL, 'Commercial financing depends on property type, income potential, borrower qualifications, lender requirements, and investment purpose.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(949, 'Mortgage & Financing', 'loan_denied', 'Why might a mortgage application be denied?', NULL, 'Applications may be denied due to credit issues, income concerns, debt levels, insufficient documentation, property issues, or lender requirements.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(950, 'Mortgage & Financing', 'mortgage_broker', 'What does a mortgage broker do?', NULL, 'A mortgage broker helps borrowers compare loan options and connect with lenders based on financial needs and qualifications.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:50:59', '2026-08-03 07:50:59'),
(951, 'Property Analysis', 'property_valuation', 'What is property valuation?', NULL, 'Property valuation is the process of estimating the market value of a property based on factors such as location, condition, features, market activity, and comparable properties.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(952, 'Property Analysis', 'home_value', 'How do I find out how much my home is worth?', NULL, 'Home value can be estimated through comparable sales, market analysis, professional valuations, appraisals, and local market conditions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(953, 'Property Analysis', 'comparative_market_analysis', 'What is a comparative market analysis (CMA)?', NULL, 'A CMA is a report that compares similar properties to help estimate a property’s likely market value and appropriate pricing strategy.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(954, 'Property Analysis', 'cma_vs_appraisal', 'What is the difference between a CMA and an appraisal?', NULL, 'A CMA is typically prepared by a real estate professional for marketing guidance, while an appraisal is a formal valuation performed by a qualified appraiser.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(955, 'Property Analysis', 'home_appraisal', 'What is a home appraisal?', NULL, 'A home appraisal is an independent evaluation of property value used for purposes such as financing, transactions, or financial decisions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(956, 'Property Analysis', 'appraisal_process', 'How does the appraisal process work?', NULL, 'An appraiser reviews the property, analyzes comparable sales, evaluates features and conditions, and prepares a value assessment.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(957, 'Property Analysis', 'appraisal_value_low', 'What happens if an appraisal is lower than the purchase price?', NULL, 'A low appraisal may require renegotiation, additional buyer funds, dispute procedures, or other solutions depending on the transaction agreement.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(958, 'Property Analysis', 'appraisal_value_high', 'What happens if an appraisal is higher than the purchase price?', NULL, 'A higher appraisal may provide immediate equity, although the transaction terms remain based on the agreed purchase price.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(959, 'Property Analysis', 'property_comparables', 'What are comparable properties?', NULL, 'Comparable properties are similar properties recently sold or currently available that help evaluate pricing and market value.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(960, 'Property Analysis', 'choose_comparables', 'How are comparable properties selected?', NULL, 'Comparables are chosen based on factors such as location, size, condition, age, features, and recent sales activity.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(961, 'Property Analysis', 'market_analysis', 'What is a real estate market analysis?', NULL, 'A market analysis examines property data, trends, competition, pricing, supply, demand, and other factors affecting real estate decisions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(962, 'Property Analysis', 'property_price_estimate', 'How accurate are online home value estimates?', NULL, 'Online estimates can provide general guidance but may not reflect unique property features, current conditions, or local market changes.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(963, 'Property Analysis', 'property_data_sources', 'What data is used to analyze real estate?', NULL, 'Real estate analysis may use sales records, listings, market trends, property details, demographics, economic information, and neighborhood data.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(964, 'Property Analysis', 'price_per_square_foot', 'What is price per square foot?', NULL, 'Price per square foot compares property price with the size of the property and is often used as one factor in market analysis.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(965, 'Property Analysis', 'gross_rental_yield', 'What is gross rental yield?', NULL, 'Gross rental yield measures annual rental income compared with the property purchase price before considering expenses.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(966, 'Property Analysis', 'net_rental_yield', 'What is net rental yield?', NULL, 'Net rental yield considers rental income after operating expenses compared with the property value or investment amount.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(967, 'Property Analysis', 'cash_on_cash_return', 'What is cash-on-cash return?', NULL, 'Cash-on-cash return measures the annual return generated from the actual cash invested in a property.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(968, 'Property Analysis', 'investment_cap_rate', 'How is cap rate calculated?', NULL, 'Cap rate is generally calculated by dividing net operating income by the property value or purchase price.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(969, 'Property Analysis', 'property_equity', 'What is property equity?', NULL, 'Property equity is the difference between the property value and the amount still owed on related loans.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(970, 'Property Analysis', 'build_home_equity', 'How can homeowners build equity?', NULL, 'Homeowners can build equity through mortgage payments, property improvements, market appreciation, and reducing loan balances.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(971, 'Property Analysis', 'property_debt_analysis', 'Why analyze property debt before buying?', NULL, 'Understanding debt obligations helps buyers and investors evaluate affordability, risk, cash flow, and long-term financial impact.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(972, 'Property Analysis', 'neighborhood_analysis', 'What is neighborhood analysis?', NULL, 'Neighborhood analysis evaluates factors such as location quality, amenities, safety, growth, demand, and future development potential.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(973, 'Property Analysis', 'property_trend_analysis', 'Why are real estate trends important?', NULL, 'Trends help buyers, sellers, and investors understand market direction, opportunities, risks, and timing considerations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(974, 'Property Analysis', 'investment_projection', 'What is a real estate investment projection?', NULL, 'An investment projection estimates possible future income, expenses, appreciation, and returns based on assumptions and market expectations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(975, 'Property Analysis', 'real_estate_analytics_tools', 'How do technology tools help with real estate analysis?', NULL, 'Analytics tools help organize data, identify trends, compare properties, evaluate investments, and support informed decisions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:20', '2026-08-03 07:51:20'),
(976, 'AI Chatbot Training', 'real_estate_ai_assistant', 'What can an AI real estate assistant do?', NULL, 'An AI real estate assistant can answer questions, provide property information, qualify leads, schedule appointments, support clients, and automate routine communication.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(977, 'AI Chatbot Training', 'chatbot_buyer_lead', 'How can a chatbot help identify home buyers?', NULL, 'A chatbot can ask about budget, preferred location, property type, timeline, financing status, and buying goals to understand buyer needs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(978, 'AI Chatbot Training', 'chatbot_seller_lead', 'How can a chatbot identify potential sellers?', NULL, 'A chatbot can ask about property ownership, selling timeline, reason for selling, property details, and goals to determine seller needs.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(979, 'AI Chatbot Training', 'lead_qualification_questions', 'What questions should a real estate chatbot ask leads?', NULL, 'A chatbot may ask about buying or selling goals, location, budget, timing, financing, property preferences, and contact information.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(980, 'AI Chatbot Training', 'chatbot_appointment_booking', 'Can a real estate chatbot schedule appointments?', NULL, 'Yes, chatbots can help schedule property tours, consultations, calls, and meetings based on available appointment options.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(981, 'AI Chatbot Training', 'chatbot_property_questions', 'Can a chatbot answer property questions?', NULL, 'A chatbot can answer common property questions using available listing information, databases, and approved knowledge sources.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(982, 'AI Chatbot Training', 'chatbot_human_handoff', 'When should a chatbot transfer a conversation to an agent?', NULL, 'A chatbot should transfer conversations when users need expert advice, negotiation support, complex answers, or personalized assistance.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(983, 'AI Chatbot Training', 'chatbot_24_hour_service', 'Can a real estate chatbot work 24/7?', NULL, 'Yes, AI chatbots can provide assistance at any time and help capture leads outside normal business hours.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(984, 'AI Chatbot Training', 'chatbot_follow_up', 'How can chatbots help with follow-ups?', NULL, 'Chatbots can send reminders, answer follow-up questions, provide updates, and help maintain communication with potential clients.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(985, 'AI Chatbot Training', 'chatbot_customer_service', 'How can AI improve real estate customer service?', NULL, 'AI improves customer service by providing faster responses, consistent information, easy access to resources, and better client engagement.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(986, 'AI Chatbot Training', 'chatbot_listing_search', 'Can a chatbot help search property listings?', NULL, 'Yes, a chatbot can collect buyer preferences and help users find suitable listings when connected with property data sources.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(987, 'AI Chatbot Training', 'chatbot_market_questions', 'Can a chatbot answer real estate market questions?', NULL, 'A chatbot can provide general market information and explain concepts, while complex market advice may require a professional agent.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(988, 'AI Chatbot Training', 'chatbot_personalization', 'How can a chatbot personalize real estate conversations?', NULL, 'Chatbots personalize conversations by remembering user preferences during sessions and tailoring responses based on collected information.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(989, 'AI Chatbot Training', 'chatbot_data_privacy', 'How should real estate chatbots handle customer data?', NULL, 'Chatbots should protect personal information, follow privacy practices, collect only necessary data, and use secure systems.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(990, 'AI Chatbot Training', 'chatbot_accuracy', 'How can I improve chatbot accuracy?', NULL, 'Improve accuracy by providing quality training data, updating information regularly, testing responses, and monitoring user interactions.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(991, 'AI Chatbot Training', 'chatbot_training_data', 'What data should be used to train a real estate chatbot?', NULL, 'Training data may include FAQs, property information, service details, processes, market explanations, policies, and common client conversations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(992, 'AI Chatbot Training', 'chatbot_intent_detection', 'What is intent detection in a chatbot?', NULL, 'Intent detection allows a chatbot to understand what a user wants, such as buying, selling, renting, investing, or requesting information.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(993, 'AI Chatbot Training', 'chatbot_entities', 'What are entities in a real estate chatbot?', NULL, 'Entities are important details extracted from conversations, such as locations, budgets, property types, dates, and preferences.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(994, 'AI Chatbot Training', 'chatbot_multilingual', 'Can real estate chatbots support multiple languages?', NULL, 'Yes, many AI chatbots can support multiple languages to serve diverse clients and improve accessibility.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(995, 'AI Chatbot Training', 'chatbot_integration', 'What systems can a real estate chatbot connect with?', NULL, 'Chatbots can integrate with CRMs, websites, calendars, listing systems, messaging platforms, and customer management tools.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(996, 'AI Chatbot Training', 'chatbot_real_estate_automation', 'What real estate tasks can chatbots automate?', NULL, 'Chatbots can automate FAQs, lead capture, appointment requests, basic qualification, follow-ups, and information delivery.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(997, 'AI Chatbot Training', 'chatbot_agent_productivity', 'How do chatbots help real estate agents save time?', NULL, 'Chatbots reduce repetitive communication, organize leads, answer common questions, and allow agents to focus on higher-value activities.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(998, 'AI Chatbot Training', 'chatbot_conversion_rate', 'Can chatbots improve real estate lead conversion?', NULL, 'Chatbots may improve conversion by responding quickly, engaging visitors, qualifying leads, and reducing delays in communication.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(999, 'AI Chatbot Training', 'chatbot_limitations', 'What are the limitations of real estate chatbots?', NULL, 'Chatbots may not replace professional judgment, negotiation skills, legal advice, or complex decision-making that requires human expertise.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44'),
(1000, 'AI Chatbot Training', 'future_ai_real_estate', 'What is the future of AI chatbots in real estate?', NULL, 'AI chatbots are expected to become more intelligent, personalized, integrated, and useful for improving client experiences and business operations.', NULL, 0, NULL, 'English', 'active', '2026-08-03 07:51:44', '2026-08-03 07:51:44');
